class Solution {
    fun addTwoNumbers(l1: ListNode?, l2: ListNode?): ListNode? {
        var n1 = l1
        var n2 = l2
        var carry = 0
        var sum: Int
        val dummyNode = ListNode(-1)
        var resultantList = dummyNode
        while (n1 != null || n2 != null) {
            sum = (n1?.`val` ?: 0) + (n2?.`val` ?: 0) + carry
            carry = sum / 10
            resultantList.next = ListNode(sum % 10)
            resultantList = resultantList.next!!
            n1 = n1?.next
            n2 = n2?.next
        }
        if (carry != 0) resultantList.next = ListNode(carry)
        return dummyNode.next
    }
}

class Solution {
    fun lengthOfLongestSubstring(s: String): Int {
        val hs = HashSet<Char>()
        var i = 0
        var j = 0
        var maxLength = 0
        while (j < s.length) {
            if (hs.contains(s[j])) {
                hs.remove(s[i++])
            } else {
                hs.add(s[j++])
                maxLength = maxLength.coerceAtLeast(hs.size)
            }
        }
        return maxLength
    }
}

class Solution {
    fun findMedianSortedArrays(nums1: IntArray, nums2: IntArray): Double {
        var i1 = 0
        var i2 = 0
        fun getNext() = when {
            i1 < nums1.size && i2 < nums2.size -> if (nums1[i1] < nums2[i2]) nums1[i1++] else nums2[i2++]
            i1 < nums1.size -> nums1[i1++]
            else -> nums2[i2++]
        }
        val arr = IntArray(nums1.size + nums2.size) { getNext() }
        return if (arr.size % 2 == 1) arr[arr.size / 2].toDouble()
        else  (arr[arr.size / 2] + arr[arr.size / 2 - 1]) / 2.0
    }
}

class Solution {
    fun longestPalindrome(s: String): String {
        var start = 0
        var maxL = 0

        for (i in 0 until s.length) {
            var l = i
            var r = i
            while (l >= 0 && r < s.length && s[l] == s[r]) {
                if (r - l + 1 > maxL) {
                    start = l
                    maxL = (r - l + 1)
                }
                l--
                r++
            }

            l = i
            r = i + 1
            while (l >= 0 && r < s.length && s[l] == s[r]) {
                if (r - l + 1 > maxL) {
                    start = l
                    maxL = (r - l + 1)
                }
                l--
                r++
            }
        }

        return s.substring(start, start + maxL)
    }
}

class Solution {
    fun convert(s: String, numRows: Int): String {
        if (numRows == 1) return s

        val res = StringBuilder()
        for (r in 0 until numRows) {
            val increment = 2 * (numRows - 1)
            for (i in r until s.length step increment) {
                res.append(s[i])
                if (r > 0 && r < numRows - 1
                    && i + increment - 2 * r < s.length)
                    res.append(s[i + increment - 2 * r])
            }
        }

        return res.toString()
    }
}

class Solution {
    fun reverse(x: Int): Int {
        val MIN = Int.MIN_VALUE
        val MAX = Int.MAX_VALUE

        var res = 0
        var value = x
        while (value != 0) {
            var digit = value % 10
            value /= 10

            if (res > MAX / 10 || (res == MAX / 10 && digit >= MAX % 10)) {
                return 0
            }
            if (res < MIN / 10 || (res == MIN / 10 && digit <= MIN % 10)) {
                return 0
            }
            res = (res * 10) + digit
        }
        return res
    }
}

class Solution {
    fun isPalindrome(x: Int): Boolean {
        if (x < 0) return false

        var reverse = 0
        var x2 = x
        while (x2 != 0) {
            reverse *= 10
            reverse += x2 % 10
            x2 /= 10
        }

        return reverse == x
    }
}

