class Solution {
    fun isMatch(s: String, p: String): Boolean {
        val cache = Array (s.length + 1) { IntArray (p.length + 1) { -1 } }

        fun dfs(i: Int, j: Int): Int {
            if (i >= s.length && j >= p.length)
                return 1
            if (j >= p.length)
                return 0
            if (cache[i][j] != -1)
                return cache[i][j]

            val charMatched = i < s.length && (s[i] == p[j] || p[j] == '.')

            if (j + 1 < p.length && p[j + 1] == '*')
                return if (dfs(i, j + 2) == 1 || charMatched && dfs(i + 1, j) == 1) 1 else 0
            if (charMatched)
                return dfs(i + 1, j + 1)

            cache[i][j] == 0
            return 0
        }

        return dfs(0, 0) == 1
    }
}

class Solution {
    fun maxArea(heights: IntArray): Int {

        if(heights.isEmpty()) return 0

        val size = heights.size
        var lo = 0
        var hi = size -1
        var maxArea = 0

        while(lo < hi){
            val area = minOf(heights[lo], heights[hi]) * (hi - lo)
            maxArea = maxOf(maxArea, area)

            if(heights[lo] < heights[hi])
                ++lo
            else --hi
        }

        return maxArea
    }
}

class Solution {
    fun intToRoman(_num: Int): String {
        val symList = listOf(
            "I" to 1,
            "IV" to 4,
            "V" to 5,
            "IX" to 9,
            "X" to 10,
            "XL" to 40,
            "L" to 50,
            "XC" to 90,
            "C" to 100,
            "CD" to 400,
            "D" to 500,
            "CM" to 900,
            "M" to 1000
        )

        return buildString {
            var num = _num
            for ((sym, value) in symList.reversed()) {
                if (num / value > 0) {
                    val count = num / value
                    append(sym.repeat(count))
                    num = num % value
                }
            }
        }
    }
}

class Solution {
    fun romanToInt(s: String): Int {
        val roman = mapOf(
            'I' to 1,
            'V' to 5,
            'X' to 10,
            'L' to 50,
            'C' to 100,
            'D' to 500,
            'M' to 1000
        )

        var res = 0
        for (i in s.indices) {
            if (i + 1 < s.length && roman[s[i]]!! < roman[s[i + 1]]!!)
                res -= roman[s[i]]!!
            else
                res += roman[s[i]]!!
        }

        return res
    }
}

