class Solution {
    fun removeNthFromEnd(head: ListNode?, n: Int): ListNode? {
        var fastPointer = head
        var slowPointer: ListNode? = null
        var i = 1
        while (fastPointer != null && i <= n) {
            fastPointer = fastPointer.next
            i++
        }
        while (fastPointer != null) {
            slowPointer = if (slowPointer == null) head else slowPointer.next
            fastPointer = fastPointer.next
        }
        slowPointer?.next = slowPointer?.next?.next
        return if (slowPointer == null) head?.next else head
    }
}

class Solution {
    fun isValid(s: String): Boolean {
        if (s.length % 2 == 1) return false

        val map = hashMapOf('(' to ')', '[' to ']', '{' to '}')
        val stack = Stack<Char>()

        for (c in s) {
            if (map.containsKey(c))
                stack.push(c)
            else if (stack.isEmpty() || map[stack.pop()] != c)
                return false
        }
        return stack.isEmpty()
    }
}

class Solution {
    fun mergeTwoLists(l1: ListNode?, l2: ListNode?): ListNode? {
        var r1 = l1
        var r2 = l2
        val ll = ListNode(0)
        var rr = ll
        while(true){
            if(r1==null && r2==null){
                break
            }
            if(r1==null){
                rr.next = r2
                break
            }
            if(r2==null){
                rr.next = r1
                break
            }
            if(r1.`val`<=r2.`val`){
                rr.next = r1
                r1 = r1.next
            }
            else{
                rr.next = r2
                r2 = r2.next
            }
            rr = rr.next
        }
        return ll.next
    }
}

class Solution {
    private val resultList = mutableListOf<String>()

    fun generateParenthesis(n: Int): List<String> {
        generateParenthesis(n * 2, "")
        return resultList
    }

    private fun generateParenthesis(target: Int, current: String) {
        if (current.length == target) {
            var open = 0
            var close = 0
            for (i in 0 until current.length) {
                if (current[i] == '(') {
                    ++open
                } else {
                    ++close
                }
                if (close > open) {
                    break
                }
            }
            if (close == open) {
                resultList.add(current)
            }
        } else {
            generateParenthesis(target, "${current}(")
            generateParenthesis(target, "${current})")
        }
    }
}

