        if (idx >= nums.size || target < 0)
            return

        for (i in idx..nums.size-1) {
            if (i == idx || nums[i] != nums[i-1]) {
                list.add(nums[i])
                dfs(nums, target - nums[i], i+1, list, res)
                list.removeAt(list.size-1)
            }
        }
    }
}

class Solution {
    fun firstMissingPositive(nums: IntArray): Int {
        var i = 0
        // if we encounter a valid integer, swap it into its right place. Ignore all numbers larger than nums.length
        while(i < nums.size) {
            val pos = nums[i] - 1
            if(pos in (0 until nums.size) && nums[i] != nums[pos]) nums.swap(i, pos)
            else i++
        }

        //if the expected number is not in its right place, return it
        for(i in nums.indices){
            if (nums[i] != i + 1) return i + 1
        }
        return nums.size + 1
    }
    private fun IntArray.swap(i: Int, j: Int) {
        this[i] = this[j].also{ this[j] = this[i]}
    }
}

import kotlin.math.max

class Solution {
    fun trap(height: IntArray): Int {
        var volumeOfWaterTrapped = 0
        var l = 0
        var r = height.lastIndex
        var currentLeftMax = -1
        var currentRightMax = -1

        while (l < r) {
            if (height[l] <= height[r]) {
                currentLeftMax = max(currentLeftMax, height[l])
                l++
                volumeOfWaterTrapped += (currentLeftMax - height[l]).coerceAtLeast(0)
            } else {
                currentRightMax = max(currentRightMax, height[r])
                r--
                volumeOfWaterTrapped += (currentRightMax - height[r]).coerceAtLeast(0)
            }
        }
        return volumeOfWaterTrapped
    }
}

class Solution {
    fun multiply(num1: String, num2: String): String {
        if (num1=="0" || num2=="0") return "0"

        val sum = IntArray(num1.length + num2.length)
        val n1 = num1.reversed()
        val n2 = num2.reversed()

        for (i in 0 until n1.length) {
            for (j in 0 until n2.length) {
                var temp = (n1[i] - '0') * (n2[j] - '0') + sum[i + j]
                sum[i + j + 1] += temp / 10
                sum[i + j] = temp % 10
            }
        }

        return StringBuilder().apply {
            for(i in sum.lastIndex downTo 0) {
                if (this.length == 0 && sum[i] == 0) continue
                this.append(sum[i])
            }
        }.toString()

    }
}

/*
* O(n) BFS
*/
class Solution {
    fun jump(nums: IntArray): Int {
        var left = 0
        var right = 0
        var res = 0

        while (right < nums.size - 1) {
            var maxJump = 0
            for (i in left..right) {
                maxJump = maxOf(maxJump, i + nums[i])
            }
            left = right + 1
            right = maxJump
            res += 1
        }
        return res
    }
}

/*
* O(N^2) DP + memoization
*/
class Solution {
    fun jump(nums: IntArray): Int {
        val dp = IntArray(nums.size) { 10001 }

        fun jump(i: Int): Int {
            if (i == nums.lastIndex)
                return 0
            if (dp[i] != 10001)
                return dp[i]

            for (steps in 1..nums[i]) {
                if (i + steps <= nums.lastIndex) {
                    dp[i] = minOf(
                        dp[i],
                        1 + jump(i + steps)
                    )
                }
            }

            return dp[i]
        }

        return jump(0)
    }
}

