class Solution {
    fun permute(nums: IntArray): List<MutableList<Int>> {
        val res = mutableListOf<MutableList<Int>>()
        val queue = ArrayDeque<Int>(nums.toList())

        // base case
        if (queue.size == 1) {
            return listOf(queue.toMutableList()) // queue.toList() is a deep copy
        }

        for (i in nums.indices) {
            val n = queue.removeFirst()
            val perms = permute(queue.toIntArray())

            for (perm in perms) {
                perm.add(n)
                res.add(perm)
            }
            queue.addLast(n)
        }
        return res
    }
}

// original solution
class Solution {
    fun permute(nums: IntArray): List<List<Int>> {
        val res = mutableListOf<List<Int>>()
        permute(nums, mutableSetOf<Int>(), mutableListOf<Int>(), res)
        return res
    }

    fun permute(nums: IntArray, set: MutableSet<Int>, list: MutableList<Int>, res: MutableList<List<Int>>) {
        if (list.size == nums.size) {
            res.add(ArrayList(list))
            return
        }

        for (i in 0..nums.size-1) {
            if (!set.contains(nums[i])) {
                list.add(nums[i])
                set.add(nums[i])
                permute(nums, set, list, res)
                list.removeAt(list.size-1)
                set.remove(nums[i])
            }
        }
    }
}

class Solution {
    fun permuteUnique(nums: IntArray): List<List<Int>> {
        val count = HashMap<Int, Int>()
        val permut = LinkedList<Int>()
        val res = LinkedList<LinkedList<Int>>()

        for (n in nums) count[n] = count.getOrDefault(n, 0) + 1

        fun backtrack() {
            if (permut.size == nums.size) {
                res.add(LinkedList(permut))
                return
            }

            for (n in count.keys) {
                if (count[n]!! > 0) {
                    permut.addLast(n)
                    count[n] = count[n]!! - 1

                    backtrack()

                    count[n] = count[n]!! + 1
                    permut.removeLast()
                }
            }
        }

        backtrack()
        return res
    }
}

class Solution {
    fun rotate(matrix: Array<IntArray>): Unit {
        var left = 0; var right = matrix.size-1
        while (left < right){
            for(i in 0..(right-left)-1){
                val top = left; val bot = right
                val topleft = matrix[top][left+i]
                matrix[top][left+i] = matrix[bot-i][left]
                matrix[bot-i][left] = matrix[bot][right-i]
                matrix[bot][right-i] = matrix[top+i][right]
                matrix[top+i][right] = topleft
            }
            left++
            right--
        }
    }
}

