fun groupAnagrams(strs: Array<String>): List<List<String>> {
    val res: HashMap<String, MutableList<String>> = hashMapOf()

    for (s in strs){
        val count = IntArray(26)

        for (c in s){
            val index = c - 'a'
            count[index] += 1
        }

        res[count.joinToString()] = res.getOrDefault(count.joinToString(), mutableListOf()).also { it.add(s) }
    }

    return res.values.toList()
}

class Solution {
    fun myPow(x: Double, n: Int): Double {
        val sum = myPowHelper(x, n)
        return if(n < 0) 1/sum else sum // if power to the negative
    }
    private fun myPowHelper(x: Double, n: Int): Double {
        if(x == 0.0)
            return 0.0
        when(n){
            0 -> return 1.0
            1 -> return x
            else -> {
                var res = myPowHelper(x, n/2)
                res *= res
                return if(n%2==0) res else x * res //if odd number, we multiply the "lost" number from integer division
            }
        }
    }
}

class Solution {
    fun solveNQueens(n: Int): List<List<String>> {
        val cols = HashSet<Int>() //keep track of used columns, we iterate rows
        val posDia = HashSet<Int>() //...of positive diagonals R+C
        val negDia = HashSet<Int>() //...of negative diagonals R-C
        val temp: ArrayList<ArrayList<String>> = arrayListOf() // to hold our temporary distinct solution
        val res: ArrayList<ArrayList<String>> = arrayListOf() // result with each distinct solutin where each input is a solution
        fillWithQueens(0,n,res,cols,posDia,negDia,temp)
        return res
    }
    private fun fillWithQueens(
        row: Int,
        n: Int,
        res: ArrayList<ArrayList<String>>,
        cols: HashSet<Int>,
        posDia: HashSet<Int>,
        negDia: HashSet<Int>,
        board: ArrayList<ArrayList<String>>
    ){
        //if we have filled the whole board with queens
        if(row == n){
            val complete: ArrayList<String> = arrayListOf()
            for(i in 0..n-1){
                val joined = board[i].joinToString(separator = "")
                complete.add(joined)
            }
            res.add(complete)
            return
        }
        for(column in 0 until n){
            if(cols.contains(column) || posDia.contains(row+column) || negDia.contains(row-column))
                continue
            val temp = tempRow(n)
            board.add(temp)
            cols.add(column)
            posDia.add(row+column)
            negDia.add(row-column)
            board[row][column] = "Q"
            fillWithQueens(row+1,n,res,cols,posDia,negDia,board)
            cols.remove(column)
            posDia.remove(row+column)
            negDia.remove(row-column)
            board[row][column] = "."
        }
    }
    private fun tempRow(n: Int): ArrayList<String>{
        val temp: ArrayList<String> = arrayListOf()
        repeat(n){
                temp.add(".")
            }
        return temp
    }
}

class Solution {
    fun totalNQueens(n: Int): Int {

        val cols = HashSet<Int>()
        val pD = HashSet<Int>()
        val nD = HashSet<Int>()
        var res = 0

        fun fill(row: Int) {

            if(row == n) {
                res++
                return
            }

            for(col in 0 until n) {
                if(cols.contains(col) || pD.contains(row + col) || nD.contains(row - col)) continue

                cols.add(col)
                pD.add(row + col)
                nD.add(row - col)

                fill(row+1)

                cols.remove(col)
                pD.remove(row + col)
                nD.remove(row - col)
            }
        }

        fill(0)
        return res
    }
}

class Solution {
    fun maxSubArray(nums: IntArray): Int {
        var sum = nums[0]
        var currsum = 0
        for (num in nums) {
            currsum = maxOf(currsum + num, num)
            sum = maxOf(currsum, sum)
        }
        return sum
    }
}

