/*
* O(n) greedy
*/
class Solution {
    fun canJump(nums: IntArray): Boolean {
        var goal = nums.size - 1

        for (i in nums.size - 2 downTo 0) {
            if (i + nums[i] >= goal) {
                goal = i
            }
        }
        return goal == 0
    }
}

/*
* O(n^2) DP + memoization
*/
class Solution {
    fun canJump(nums: IntArray): Boolean {
        val deadEnd = BooleanArray(nums.size)

        fun canJump(i: Int): Boolean {
            if (i == nums.lastIndex)
                return true
            if (nums[i] == 0 || deadEnd[i] == true)
                return false

            for (jump in 1..nums[i]) {
                if (i + jump <= nums.lastIndex && canJump(i + jump)) {
                    return true
                }
            }

            deadEnd[i] = true
            return false
        }

        return canJump(0)
    }
}

class Solution {
    fun merge(intervals: Array<IntArray>): Array<IntArray> {
        intervals.sortBy{ it.first() }
        val list = LinkedList<IntArray>()

        for (interval in intervals) {
            if (list.size == 0 || list.last[1] < interval[0]) {
                list.add(interval)
            } else {
                list.last[1] = Math.max(list.last[1], interval[1])
            }
        }

        return list.toTypedArray()
    }
}

class Solution {
    fun insert(intervals: Array<IntArray>, newInterval: IntArray): Array<IntArray> {
        val res = ArrayList<IntArray>()
        var added = false
        var index = 0
        for(i in 0 until intervals.size){
            val interval = intervals[i]
            if(newInterval[1] < interval[0]){ //no more overlapping intervals
                res.add(newInterval)
                added = true
                break
            }else if(newInterval[0] > interval[1]){ //non overlapping
                res.add(interval)
            }else{ //overlapping, update the newinterval accordingly
                newInterval[0] = minOf(newInterval[0],interval[0])
                newInterval[1] = maxOf(newInterval[1],interval[1])
            }
            index++
        }
        if(index < intervals.size){ // add all the leftover intervals (after the break)
            for(i in index until intervals.size)
                res.add(intervals[i])
        }
        if(added == false) // takes care of (1) Empty intervals array or 1-sized array with overlapping newinterval
            res.add(newInterval)
        return res.toTypedArray()
    }
}

