class Solution {
    fun generateMatrix(n: Int): Array<IntArray> {
        var left = 0
        var right = n - 1
        var top = 0
        var bot = n - 1
        var count = 1
        val m = Array(n) { IntArray(n) }

        while (left <= right && top <= bot) {
            for (i in left..right)
                m[top][i] = count++
            top++

            for (i in top..bot)
                m[i][right] = count++
            right--

            if (left > right || top > bot)
               break

            for (i in right downTo left)
                m[bot][i] = count++
            bot--

            for (i in bot downTo top)
                m[i][left] = count++
            left++
        }

        return m
    }
}

class Solution {
    fun rotateRight(head: ListNode?, _k: Int): ListNode? {
        head?: return null

        var length = 1
        var tail = head
        while (tail?.next != null) {
            tail = tail?.next
            length++
        }

        val k = _k % length
        if (k == 0) return head

        var cur = head
        for (i in 0 until (length - k - 1))
            cur = cur?.next

        val newHead = cur?.next
        cur?.next = null
        tail?.next = head

        return newHead
    }
}

class Solution {
    fun uniquePaths(m: Int, n: Int): Int {
      val dp = Array(m + 1) { IntArray(n + 1) { 0 } }
        val indexM = m - 1
        val indexN = n - 1
        for (i in indexM downTo 0) {
            for (j in indexN downTo 0) {
                if (i == indexM && j == indexN) {
                    dp[i][j] = 1
                } else {
                    dp[i][j] = dp[i + 1][j] + dp[i][j + 1]
                }
            }
        }
        return dp[0][0]
    }
}

// If we can't do inplace, space O(N)
class Solution {
    fun uniquePathsWithObstacles(grid: Array<IntArray>): Int {

        val m = grid.lastIndex
        val n = grid[0].lastIndex

        if (grid[m][n] == 1 || grid[0][0] == 1) return 0

        val dp = IntArray(n+1)
        dp[n] = 1

        for (i in m downTo 0) {
            for (j in n downTo 0) {
                if (grid[i][j] == 1) dp[j] = 0
                else if (j < n) dp[j] = dp[j] + dp[j + 1]
                //else dp[j] = dp[j] + 0
            }
        }

        return dp[0]
    }
}

// In place O(1)
class Solution {
    fun uniquePathsWithObstacles(grid: Array<IntArray>): Int {

        val m = grid.lastIndex
        val n = grid[0].lastIndex

        if (grid[m][n] == 1 || grid[0][0] == 1) return 0

        grid[m][n] = 1

        for (i in m-1 downTo 0) {
            grid[i][n] = if(grid[i][n] == 0 && grid[i + 1][n] == 1) 1 else 0
        }

        for (i in n-1 downTo 0) {
            grid[m][i] = if(grid[m][i] == 0 && grid[m][i + 1] == 1) 1 else 0
        }

        for (i in m-1 downTo 0) {
            for (j in n-1 downTo 0) {
                if(grid[i][j] != 1) {
                    grid[i][j] = grid[i + 1][j] + grid[i][j + 1]
                } else {
                    grid[i][j] = 0
                }
            }
        }

        return grid[0][0]
    }
}

class Solution {
    fun minPathSum(grid: Array<IntArray>): Int {
        val m = grid.lastIndex
        val n = grid[0].lastIndex

        for(i in m - 1 downTo 0) {
            grid[i][n] += grid[i + 1][n]
        }

        for(j in n - 1 downTo 0) {
            grid[m][j] += grid[m][j + 1]
        }

        for(i in grid.lastIndex - 1 downTo 0) {
            for(j in grid[0].lastIndex - 1 downTo 0) {
                grid[i][j] += minOf(grid[i + 1][j], grid[i][j + 1])
            }
        }

        return grid[0][0]
    }
}

