class Solution {
    fun addBinary(a: String, b: String): String {
        var rsum = ""; var carry = 0; var aL = a.length-1; var bL = b.length-1
        while(aL >= 0 || bL >= 0){
            var aBit = if(aL >= 0) a[aL--] else '0'
            var bBit = if(bL >= 0) b[bL--] else '0'
            val sum = aBit.toString().toInt() + bBit.toString().toInt() + carry
            carry = sum / 2
            rsum = (sum % 2).toString() + rsum
        }
        if(carry > 0)
            rsum = '1' + rsum
        return rsum
    }
}

//opted out of using StringBuilder, instead used Kotlins plus operator to create new Strings
class Solution {
    fun fullJustify(words: Array<String>, maxWidth: Int): List<String> {
        val res = mutableListOf<String>()
        var line = mutableListOf<String>()
        var length = 0
        var i = 0

        while (i < words.size) {
            if (length + line.size + words[i].length > maxWidth) {
                val extraSpace = maxWidth - length
                val spaces = extraSpace / maxOf(1, line.size - 1)
                var remainder = extraSpace % maxOf(1, line.size - 1)

                for (j in 0 until maxOf(1, line.lastIndex)) {
                    line[j] += " ".repeat(spaces)
                    if (remainder > 0) {
                        line[j] += " "
                        remainder--
                    }
                }

                var whole = ""
                for (l in line) whole += l
                res.add(whole)
                line.clear()
                length = 0
            }

            line.add(words[i])
            length += words[i].length
            i++
        }

        var lastLine = "" + line.joinToString(" ")
        val trailSpace = maxWidth - lastLine.length
        lastLine += " ".repeat(trailSpace)
        res.add(lastLine)

        return res
    }
}

/*
* Binary Search
*/
class Solution {
    fun mySqrt(x: Int): Int {
        var left = 0L
        var right = x.toLong()
        var res = 0L

        while (left <= right) {
            val mid = left + (right - left) / 2
            val midSq = mid * mid

            if (midSq > x) {
                right = mid - 1
            } else if (midSq < x) {
                left = mid + 1
                res = mid
            } else {
                return mid.toInt()
            }
        }

        return res.toInt()
    }
}

/*
* Newton's method
