class Solution {
    fun simplifyPath(path: String): String {
        val stack = LinkedList<String>()
        val invalids = hashSetOf("", ".", "..")

        path.split("/").forEach{
            if(it == ".." && stack.isNotEmpty()) {
                stack.removeLast()
            } else if (it !in invalids) {
                stack.addLast(it)
            }
        }

        return if(stack.isEmpty()) "/" else StringBuilder().apply{
            while (stack.isNotEmpty()) {
                this.append("/")
                this.append(stack.removeFirst())
            }
        }.toString()
    }
}

class Solution {
    fun setZeroes(matrix: Array<IntArray>): Unit {
        var m = matrix.size
        var n = matrix[0].size
        var isCol = false

        for (i in 0..m-1) {
            if (matrix[i][0] == 0)
                isCol = true

            for (j in 1..n-1) {
                if (matrix[i][j] == 0) {
                    matrix[i][0] = 0
                    matrix[0][j] = 0
                }
            }
        }

        for (i in 1..m-1) {
            for (j in 1..n-1) {
                if (matrix[0][j] == 0 || matrix[i][0] == 0)
                    matrix[i][j] = 0
            }
        }

        if (matrix[0][0] == 0) {
            for (j in 0..n-1)
                matrix[0][j] = 0
        }

        if (isCol) {
            for (i in 0..m-1)
                matrix[i][0] = 0
        }
    }
}

// binary search on rows to find row, then binary search on actual row O(log(m*n))
class Solution {
    // TC: O(log m + log n)
    fun searchMatrix(matrix: Array<IntArray>, target: Int): Boolean {
        var row = matrix.size
        var col = matrix.first().size
        var top = 0
        var bot = row - 1

        while ( top <= bot ){
            row = (top + bot ) / 2
            if(target > matrix[row][col - 1]){
                top = row + 1
            } else if(target < matrix[row][0]) {
                bot = row - 1
            } else {
                break
            }
        }

        if((top > bot)) return false

        row = (top + bot) / 2
        var l = 0
        var r = col - 1
        while(l <= r){
            var m = (l + r) / 2
            if(target > matrix[row][m]){
                l = m + 1
            } else if(target < matrix[row][m]){
                r = m - 1
            } else {
                return true
            }
        }

        return false
    }
}

//binary search on whole matrix (search the matrix as an sorted array) O(log(m*n))
class Solution {
    fun searchMatrix(mt: Array<IntArray>, t: Int): Boolean {
        val rows = mt.size
        val cols = mt[0].size

        var l = 0
        var r = rows * cols - 1
        while (l != r) {
            val m = (l + r) / 2
            if (mt[m / cols][m % cols] < t)
                l = m + 1
            else
                r = m
        }

        return mt[r / cols][r % cols] == t
    }
}

//treat the matrix as an BST, root at mt[0][-1] O(m + n)
class Solution {
    fun searchMatrix(mt: Array<IntArray>, t: Int): Boolean {
        val rows = mt.size
        val cols = mt[0].size

        var row = 0
        var col = cols - 1
        while (row < rows && col >= 0) {
            val cur = mt[row][col]
            if (cur > t)
                col--
            else if (cur < t)
                row++
            else
                return true
        }

        return false
    }
}

class Solution {
    fun sortColors(nums: IntArray): Unit {

        var low = 0
        var high = nums.size-1
        var pointer = 0

        while(pointer <= high){
            when(nums[pointer]){
                0 -> {
                    swap(low,pointer,nums)
                    low++
                    pointer++
                }
                1 -> {
                    pointer++
                }
                2 -> {
                    swap(high,pointer,nums)
                    high--
                }
            }
        }
    }

    private fun swap(i: Int, j: Int, nums: IntArray){
        val temp = nums[i]
        nums[i] = nums[j]
        nums[j] = temp
    }
}

class Solution {
    fun minWindow(s: String, t: String): String {
        val lenS = s.length
        val lenT = t.length

        val freqs = IntArray(128){ 0 }
        for(ch in t){
            ++freqs[ch.toInt()]
        }

        var shortest = ""
        var count = lenT
        var lo = 0
        var hi = 0

        while(hi < lenS){
            if(freqs[s[hi].toInt()]-- > 0) --count

            while(count == 0){
                if(shortest.isEmpty() || hi - lo + 1 < shortest.length){
                    shortest = s.substring(lo, hi + 1)
                }

                if(++freqs[s[lo].toInt()] > 0) ++count
                ++lo
            }

            ++hi
        }

        return shortest
    }
}

class Solution {
    fun combine(n: Int, k: Int): List<List<Int>> {

        val res = ArrayList<ArrayList<Int>>()

        fun backtrack(start: Int, comb: ArrayList<Int>) {
            if(comb.size == k) {
                res.add(ArrayList(comb))
                return
            }

            for(i in start..n) {
                comb.add(i)
                backtrack(i + 1, comb)
                comb.removeAt(comb.size-1)
            }
        }

        backtrack(1, ArrayList<Int>())
        return res
    }
}

class Solution {
