        subsets(nums, 0, mutableListOf<Int>(), res)
        return res
    }

    fun subsets(nums: IntArray, idx: Int, list: MutableList<Int>, res: MutableList<List<Int>>) {
        res.add(ArrayList(list))

        for (i in idx..nums.size-1) {
            list.add(nums[i])
            subsets(nums, i+1, list, res)
            list.removeAt(list.size-1)
        }
    }
}

class Solution {
var ROWS: Int = 0
var COLS: Int = 0


    fun exist(board: Array<CharArray>, word: String): Boolean {

        ROWS = board.count()
        COLS = board[0].count()

        for (row in 0 until ROWS) {
            for (col in 0 until COLS) {
                if (dfs(board, row, col, word, 0))
                    return true
            }
        }


        return false
    }

    fun dfs(board: Array<CharArray>, row: Int, col: Int, word: String, indx: Int): Boolean {
        /* Step 1). check the bottom case. */
        if (indx == word.count())
            return true
        /* Step 2). Check the boundaries. */
        if (row < 0 || row == ROWS || col < 0 || col == COLS || board[row][col] != word[indx])
            return false

        // mark the path before the next exploration
        board[row][col] = '#'
        var found = false
        val rowOffsets = intArrayOf(0, 1, 0, -1)
        val colOffsets = intArrayOf(1, 0, -1, 0)

        for (i in 0..3) {
            found = dfs(board, row + rowOffsets[i], col + colOffsets[i], word, indx + 1)
            if (found)
                break

        }
        /* Step 4). clean up and return the result. */
        board[row][col] = word[indx]

        return found
    }



}

class Solution {
    fun removeDuplicates(nums: IntArray): Int {

        var left = 0
        var right = 0

        while (right < nums.size) {
            var count = 1
            while(right + 1 < nums.size && nums[right] == nums[right + 1]) {
                count++
                right++
            }
            for(i in 0 until minOf(2, count)) {
                nums[left] = nums[right]
                left++
            }
            right++
        }

        return left
    }
}

class Solution {
    fun search(nums: IntArray, target: Int): Boolean {
        var l = 0
        var r = nums.lastIndex
        while (l <= r) {
            val m = l + (r - l) / 2
            if (nums[m] == target)
                return true
            if (nums[l] < nums[m]) {
                if (nums[l] <= target && nums[m] > target)
                    r = m - 1
                else
                    l = m + 1
            } else if (nums[l] > nums[m]) {
                if (nums[r] >= target && nums[m] < target)
                    l = m + 1
                else
                    r = m - 1
            } else {
                l++
            }
        }

        return false
    }
}

