 */
class Solution {
    fun deleteDuplicates(head: ListNode?): ListNode? {
        var dummy = ListNode(Integer.MAX_VALUE, head)
        var prev = dummy
        var current = head

        while(current != null) {
            if(current.`val` == prev.`val`)
                prev.next = current.next
            else
                prev = current
            current = current.next
        }

        return dummy.next
    }
}

class Solution {
    fun largestRectangleArea(heights: IntArray): Int {
        val st = LinkedList<IntArray>()
        st.push(intArrayOf(-1, 0))
        var max = 0

        for (i in heights.indices) {
            var start = i

            while (!st.isEmpty() && st.peek()[1] > heights[i]) {
                val curr = st.pop()
                val height = curr[1]
                start = curr[0]
                max = Math.max(max, height * (i - start))
            }

            st.push(intArrayOf(start, heights[i]))
        }

        while (!st.isEmpty()) {
            val curr = st.pop()
            max = Math.max(max, curr[1] * (heights.size - curr[0]))
        }

        return max
    }
}

class Solution {
    fun partition(head: ListNode?, x: Int): ListNode? {
        var leftPart = ListNode(0)
        val rightPart = ListNode(0)

        var cur = head
        var left = leftPart
        var right = rightPart

        while (cur != null) {
            if (cur.`val` < x) {
                left?.next = cur
                left = left?.next
            } else {
                right?.next = cur
                right = right?.next
            }
            cur = cur?.next
        }

        right?.next = null
        left?.next = rightPart?.next
        return leftPart?.next
    }
}

class Solution {
    fun merge(n1: IntArray, m: Int, n2: IntArray, n: Int): Unit {
        var end = n1.lastIndex
        var i = m - 1
        var j = n - 1

        while (i >= 0 && j >= 0) {
            if (n1[i] > n2[j]) {
                n1[end] = n1[i]
                i--
            } else {
                n1[end] = n2[j]
                j--
            }
            end--
        }

        while (j >= 0) {
            n1[end] = n2[j]
            j--
            end--
        }
    }
}

class Solution {
    fun subsetsWithDup(nums: IntArray): List<List<Int>> {
        nums.sort()
        val resultantList = mutableListOf<List<Int>>()
        val intermediaryList = mutableListOf<Int>()

        fun dfs(decisionIndex: Int = 0) {
            if (decisionIndex > nums.lastIndex) {
                resultantList.add(intermediaryList.toList())
                return
            }

            // decision to include nums[decisionIndex]
            intermediaryList.add(nums[decisionIndex])
            dfs(decisionIndex + 1)

            // decision to not include nums[decisionIndex]
            intermediaryList.removeAt(intermediaryList.lastIndex)
            // skipping duplicates if any
            var i = decisionIndex
            while ((i in nums.indices && i + 1 in nums.indices) && nums[i] == nums[i + 1]) i++
            dfs(i + 1)
        }
        dfs()
        return resultantList
    }
}

class Solution {
    // Time : O(n) | Space : O(n)
    fun numDecodings(string: String): Int {
        if (string.length == 1) return if (string.last() != '0') 1 else 0
        // dp array
        val numberOfDecodings = IntArray(string.length + 1).apply {
            this[lastIndex - 1] = if (string.last() == '0') 0 else 1
            this[lastIndex] = if ("${string[string.lastIndex - 1]}${string[string.lastIndex]}".toInt() <= 26) 1 else 0
        }
        for (i in (string.lastIndex - 1) downTo 0) {
            if (string[i] == '0') {
                numberOfDecodings[i] = 0
                continue
            }
            numberOfDecodings[i] += numberOfDecodings[i + 1]
            numberOfDecodings[i] += numberOfDecodings[i + 2].takeIf {
                (string[i] == '1' && string[i + 1] in '0'..'9') || (string[i] == '2' && string[i + 1] in '0'..'6')
            } ?: 0
        }
        return numberOfDecodings[0]
    }
}

class Solution {
    fun reverseBetween(head: ListNode?, left: Int, right: Int): ListNode? {
        val dummy: ListNode? = ListNode(0)
        dummy?.next = head

        var cur = dummy
        repeat (left - 1) {
            cur = cur?.next
        }

        var pre = cur
        var start = cur?.next
        var end = start?.next

        repeat (right - left) {
            start?.next = end?.next
            end?.next = pre?.next
            pre?.next = end
            end = start?.next
        }

        return dummy?.next
    }
}

class Solution {
    fun restoreIpAddresses(s: String): List<String> {
        val res = mutableListOf<String>()

        fun backTrack(i: Int, dots: Int, cur: String) {
            if (dots == 4 && i == s.length) {
                res.add(cur.substring(0, cur.lastIndex))
                return
            }
            if (dots > 4) return

            for (j in i until minOf(i + 3, s.length)) {
                val digits = s.substring(i, j + 1)
                if (digits.toInt() <= 255 && (i == j || s[i] != '0'))
                    backTrack(j + 1, dots + 1, cur + digits + ".")
            }
        }

        backTrack(0, 0, "")
        return res
    }
}

