class Solution {
    fun generateTrees(n: Int): List<TreeNode?> {
        val dp = HashMap<Pair<Int, Int>, List<TreeNode?>>()

        fun generate(l: Int, r: Int): List<TreeNode?> {
            if (l == r) return arrayListOf(TreeNode(l))
            if (l > r) return arrayListOf<TreeNode?>(null)
            if (dp[l to r] != null) return dp[l to r]!!

            val res = ArrayList<TreeNode?>()
            for (i in l..r) {
                val left = generate(l, i - 1)
                val right = generate(i + 1, r)
                for (nodeLeft in left) {
                    for (nodeRight in right) {
                        val root = TreeNode(i, nodeLeft, nodeRight)
                        res.add(root)
                    }
                }
            }

            dp[l to r] = res
            return res
        }

        return generate(1, n)
    }
}

//"pure" dp
class Solution {
    fun numTrees(n: Int): Int {
        val cache = IntArray (n + 1) { 1 }

        for (node in 2..n) {
            var res = 0
            for (root in 1..node) {
                val left = root - 1
                val right = node - root
                res += cache[left] * cache[right]
            }
            cache[node] = res
        }

        return cache[n]
    }
}

//recursion + memoization
class Solution {
    fun numTrees(n: Int): Int {
        val cache = IntArray (n + 1) { -1 }

        fun count(root: Int): Int {
            if (root == 0) return 1
            if (cache[root] != -1) return cache[root]

            var res = 0
            for (left in 0 until root) {
                val right = root - left - 1
                res += count(left) * count(right)
            }

            cache[root] = res
            return res
        }

        return count(n)
    }
}

//DP
class Solution {
    fun isInterleave(s1: String, s2: String, s3: String): Boolean {

        val dp = Array(s1.length + 1) { BooleanArray(s2.length + 1) }
        val n = s1.length
        val m = s2.length

        if(n + m != s3.length) return false

        dp[n][m] = true

        for (i in n downTo 0) {
            for (j in m downTo 0) {
                if (i < n && s1[i] == s3[i+j] && dp[i + 1][j])
                    dp[i][j] = true
                if (j < m && s2[j] == s3[i+j] && dp[i][j + 1])
                    dp[i][j] = true
            }
        }

        return dp[0][0]
    }
}

//DFS with memoization
class Solution {
    fun isInterleave(s1: String, s2: String, s3: String): Boolean {

        if(s1.length + s2.length != s3.length) return false

        val memo = Array(s1.length + 1) { BooleanArray(s2.length + 1) }
        val n = s1.length
        val m = s2.length

        fun dfs(i: Int, j: Int): Boolean {

            if (i == n && j == m) return true
            if (memo[i][j] == true) return false

            if (i < n && s1[i] == s3[i+j]) {
                if (dfs(i + 1, j))
                    return true
            }
            if (j < m && s2[j] == s3[i+j]) {
                if (dfs(i, j + 1))
                    return true
            }

            memo[i][j] = true
            return false
        }

        return dfs(0,0)
    }
}

