 * var v = ti.`val`
 * Definition for a binary tree node.
 * class TreeNode(var `val`: Int) {
 *     var left: TreeNode? = null
 *     var right: TreeNode? = null
 * }
 */
class Solution {
    fun maxDepth(root: TreeNode?): Int {
        if (root == null)
            return 0

        val left = maxDepth(root.left)
        val right = maxDepth(root.right)

        return 1 + Math.max(left, right)
    }

    fun iterativeMaxDepth(root: TreeNode?): Int {
        if (root == null) return 0
        val callStack = Stack<Pair<TreeNode, Int>>().apply { add(Pair(root, 1)) }
        var currentMaxDepth = 1
        var temp: Pair<TreeNode, Int>
        while (callStack.isNotEmpty()) {
            temp = callStack.pop()
            currentMaxDepth = maxOf(currentMaxDepth, temp.second)
            with(temp.first) {
                left?.let { callStack.add(Pair(it, currentMaxDepth + 1)) }
                right?.let { callStack.add(Pair(it, currentMaxDepth + 1)) }
            }
        }
        return currentMaxDepth
    }
}

/**
 * Example:
 * var ti = TreeNode(5)
 * var v = ti.`val`
 * Definition for a binary tree node.
 * class TreeNode(var `val`: Int) {
 *     var left: TreeNode? = null
 *     var right: TreeNode? = null
 * }
 */
class Solution {
    fun buildTree(preorder: IntArray, inorder: IntArray): TreeNode? {
        val prStart = 0; val inStart = 0
        val prEnd = preorder.size-1; val inEnd = inorder.size-1

        return helper(preorder, prStart, prEnd, inorder, inStart, inEnd);
    }

    fun helper(preorder: IntArray, prStart: Int, prEnd: Int, inorder: IntArray, inStart: Int, inEnd: Int): TreeNode? {
        if (prStart > prEnd || inStart > inEnd)
            return null

        val root = TreeNode(preorder[prStart])
        var i = 0

        while (i < inorder.size && inorder[i] != preorder[prStart]) {
            i++
        }

        root.left = helper(preorder, prStart+1, prStart-inStart+i, inorder, inStart, i-1)
        root.right = helper(preorder, prStart-inStart+i+1, prEnd, inorder, i+1, inEnd)

        return root
    }
}

/**
 * Example:
 * var ti = TreeNode(5)
 * var v = ti.`val`
 * Definition for a binary tree node.
 * class TreeNode(var `val`: Int) {
 *     var left: TreeNode? = null
 *     var right: TreeNode? = null
 * }
 */
class Solution {
    fun buildTree(inorder: IntArray, postorder: IntArray): TreeNode? {
        val inOrdIdx = HashMap<Int, Int>().apply{
            for((i,v) in inorder.withIndex())
                this[v] = i
        }

        var pstOrdIdx = postorder.lastIndex

        fun helper(left: Int, right: Int): TreeNode? {
            if(left > right)
                return null

            val root = TreeNode(postorder[pstOrdIdx])
            pstOrdIdx--

            val index = inOrdIdx[root.value]!!
            root.right = helper(index + 1, right)
            root.left = helper(left, index - 1)
            return root
        }

        return helper(0, postorder.lastIndex)
    }

    val TreeNode.value get()= this.`val`
}

/**
 * Example:
 * var ti = TreeNode(5)
 * var v = ti.`val`
 * Definition for a binary tree node.
 * class TreeNode(var `val`: Int) {
 *     var left: TreeNode? = null
 *     var right: TreeNode? = null
 * }
 */
class Solution {
    fun sortedArrayToBST(nums: IntArray): TreeNode? {

        fun createTree(left: Int, right: Int): TreeNode? {

            if(left > right) return null
            else if(left == right) return TreeNode(nums[left])

            val mid = (left + right) / 2
            val node = TreeNode(nums[mid])
            node.left = createTree(left, mid-1)
            node.right = createTree(mid+1, right)

            return node
        }

        return createTree(0, nums.lastIndex)
    }
}

