    fun hasPathSum(root: TreeNode?, targetSum: Int): Boolean {

        root?: return false

        if(root.left == null && root.right == null) return targetSum - root.value == 0
        else return hasPathSum(root.left, targetSum - root.value) || hasPathSum(root.right, targetSum - root.value)
    }

    val TreeNode.value get() = this.`val`
}

/*
* DP bottom up
*/
class Solution {
    fun numDistinct(s: String, t: String): Int {
        val dp = Array(s.length + 1) { IntArray(t.length + 1) }

        for (i in 0..s.length)
            dp[i][t.length] = 1

        for (i in s.length - 1 downTo 0) {
            for (j in t.length - 1 downTo 0) {
                if (s[i] == t[j])
                    dp[i][j] += (dp[i + 1][j + 1] + dp[i + 1][j])
                else
                    dp[i][j] += dp[i + 1][j]
            }
        }

        return dp[0][0]
    }
}

/*
* DFS + Memoization
*/
class Solution {
    fun numDistinct(s: String, t: String): Int {
        val memo = Array(s.length) { IntArray(t.length) { -1 } }

        fun dfs(i: Int, j: Int): Int {
            if (j == t.length) return 1
            if (i == s.length) return 0
            if (memo[i][j] != -1) return memo[i][j]

            if (s[i] == t[j])
                memo[i][j] = dfs(i + 1, j + 1) + dfs(i + 1, j)
            else
                memo[i][j] = dfs(i + 1, j)

            return memo[i][j]
        }

        return dfs(0, 0)
    }
}

// Time complexity O(n) and space complexity O(1) with Follow-up constraints, without using recursion
class Solution {
    fun connect(root: Node?): Node? {
        var cur = root
        var next = cur?.left

        while (cur != null && next != null) {
            cur?.left?.next = cur?.right
            if (cur?.next != null)
                cur?.right?.next = cur?.next?.left

            cur = cur?.next
            if (cur == null) {
                cur = next
                next = cur?.left
            }
        }

        return root
    }
}

// Time complexity O(n) and space complexity O(1) with Follow-up constraints using recursion
class Solution {
    fun connect(root: Node?): Node? {
        root?: return null

        root.left?.let {
            it.next = root.right
            root.right?.let {
                it.next = root.next?.left
            }
            connect(root.left)
            connect(root.right)
        }

        return root
    }
}

// Time complexity O(n) and space complexity O(logn)
class Solution {
    fun connect(root: Node?): Node? {
        with (LinkedList<Pair<Node?, Int>>()) {
            addLast(root to 0)

            while (isNotEmpty()) {
                repeat (size) {
                    val (curNode, curLevel) = removeFirst()
                    peekFirst()?.let { (nextNode, nextLevel) ->
                        if (nextLevel == curLevel)
                            curNode?.next = nextNode
                    }
                    curNode?.left?.let { addLast(it to (curLevel + 1)) }
                    curNode?.right?.let { addLast(it to (curLevel + 1)) }
                }
            }
        }

        return root
    }
}

