        val hm = HashMap<Node, Node>()
        val q = ArrayDeque<Node>()
        q.add(node)
        hm[node] = Node(node!!.`val`)
        while(!q.isEmpty()){
            val current = q.poll()
            for(n in current.neighbors){
                if(!hm.contains(n)){
                    val copy = Node(n!!.`val`)
                    hm[n] = copy
                    q.add(n)
                }
                hm[current]!!.neighbors.add(hm[n])
            }
        }
        return hm[node]
    }
