//graph dfs solution
class Solution {
    fun candy(ratings: IntArray): Int {
        val n = ratings.size
        val outdegree = IntArray (n)

        for (i in 0 until n) {
            if (i > 0 && ratings[i] > ratings[i - 1])
                outdegree[i]++
            if (i + 1 < n && ratings[i] > ratings[i + 1])
                outdegree[i]++
        }

        val q = LinkedList<Int>()
        for ((index, degree) in outdegree.withIndex()) {
            if (degree == 0)
                q.addLast(index)
        }

        val candies = IntArray (n)
        while (q.isNotEmpty()) {
            val i = q.removeFirst()

            var candy = 1
            if (i > 0 && ratings[i] > ratings[i - 1])
                candy = maxOf(candy, candies[i - 1] + 1)
            if (i < n - 1 && ratings[i] > ratings[i + 1])
                candy = maxOf(candy, candies[i + 1] + 1)
            candies[i] = candy

            if (i > 0 && ratings[i] < ratings[i - 1]) {
                outdegree[i - 1]--
                if (outdegree[i - 1] == 0)
                    q.addLast(i - 1)
            }
            if (i < n - 1 && ratings[i] < ratings[i + 1]) {
                outdegree[i + 1]--
                if (outdegree[i + 1] == 0)
                    q.addLast(i + 1)
            }
        }

        return candies.sum()!!
    }
}

