    }

    fun get(key: Int): Int {
        if (key !in hashMap) return -1
        val nodeToBeRemoved = hashMap.getValue(key)
        removeNode(nodeToBeRemoved)
        insertAtEnd(nodeToBeRemoved)
        return nodeToBeRemoved.value
    }

    fun put(key: Int, value: Int) {
        if (key in hashMap) {
            val nodeToBeMoved = hashMap.getValue(key).apply { this.value = value }
            removeNode(nodeToBeMoved)
            insertAtEnd(nodeToBeMoved)
            return
        }
        if (hashMap.size == capacity) {
            val nodeToRemove = head.next!!
            removeNode(nodeToRemove)
            hashMap.remove(nodeToRemove.key)
        }
        val newNode = Node(key, value)
        insertAtEnd(newNode)
        hashMap[key] = newNode
    }

    private fun insertAtEnd(node: Node) {
        node.apply {
            previous = tail.previous
            next = tail
        }
        tail.previous!!.next = node
        tail.previous = node
    }

    private fun removeNode(node: Node) {
        node.previous?.next = node.next
        node.next?.previous = node.previous
    }
}

class Solution {
    fun insertionSortList(head: ListNode?): ListNode? {
        val dummy = ListNode(0)
        dummy.next = head
        var prev = head
        var cur = head?.next

        while (cur != null) {
            if (prev != null && cur.value >= prev.value) {
                prev = cur
                cur = cur.next
                continue
            }

            var temp = dummy
            while (cur.value > temp.next.value)
                temp = temp.next
            prev?.next = cur.next
            cur.next = temp.next
            temp.next = cur
            cur = prev?.next
        }

        return dummy.next
    }

    val ListNode.value
        get() = this.`val`
}

class Solution {
    fun sortList(head: ListNode?): ListNode? {

        fun mid(root: ListNode?): ListNode? {
            var slow = head
            var fast = head
            var prev: ListNode? = null
            while (fast != null && fast?.next != null) {
                prev = slow
                slow = slow?.next
                fast = fast?.next?.next
            }
            prev?.next = null
            return slow
        }

        fun merge(_l1: ListNode?, _l2: ListNode?): ListNode? {
            var l1 = _l1
            var l2 = _l2
            var dummy = ListNode()
            var tail = dummy

            while (l1 != null && l2 != null) {
                if (l1.value < l2.value) {
                    tail.next = l1
                    l1 = l1?.next
                } else {
                    tail.next = l2
                    l2 = l2?.next
                }
                tail = tail?.next
            }

            if (l1 != null) tail.next = l1
            if (l2 != null) tail.next = l2

            return dummy.next
        }

        if (head == null || head.next == null)
            return head

        val mid = mid(head)
        val sortLeft = sortList(head)
        val sortRight = sortList(mid)

        return merge(sortLeft, sortRight)
    }

    val ListNode.value
        get() = this.`val`
}

class Solution {
    fun maxPoints(points: Array<IntArray>): Int {
        val n = points.size

        var res = 1
        for (i in 0 until n) {
            val p1 = points[i]
            val count = HashMap<Double, Int>()

            for (j in i + 1 until n) {
                val p2 = points[j]

                val slope = when {
                    p1[1] == p2[1] -> 0.0
                    p1[0] != p2[0] -> (p1[1] - p2[1]) * 1.0 / (p1[0] - p2[0])
                    else -> Double.MAX_VALUE
                }

                count[slope] = count.getOrDefault(slope, 0) + 1
                res = maxOf(res, (count[slope] ?: 0) + 1)
            }
        }

        return res
    }
}

