class Solution {
    fun findMin(nums: IntArray): Int {
        var l = 0
        var r = nums.lastIndex
        var res = nums[0]

        while (l <= r) {
            var mid = l + (r - l) / 2
            if (nums[l] < nums[r]) {
                res = minOf(res, nums[l])
                break
            }

            val m = l + (r - l) / 2
            res = minOf(res, nums[m])
            if (nums[m] >= nums[l])
                l = mid + 1
            else
                r = m - 1
        }

        return res
    }
}

class MinStack() {
    private val stack = Stack<Int>()
    private val minStack = Stack<Int>()

    fun push(`val`: Int) {
        val currentMin = if (minStack.isNotEmpty()) minStack.peek() else Integer.MAX_VALUE
        val newMin = minOf(currentMin, `val`)
        stack.push(`val`)
        minStack.push(newMin)
    }

    fun pop() {
        if (stack.isNotEmpty()) {
            stack.pop()
            minStack.pop()
        }
    }

    fun top(): Int {
        return stack.peek()
    }

    fun getMin(): Int {
        return minStack.peek()
    }
}

