class Solution {
    fun rangeBitwiseAnd(left: Int, right: Int): Int {
        var res = 0

        for (i in 0 until 32) {
            val bit = (left shr i) and 1
            if (bit == 0) continue

            val remain = left % (1 shl (i + 1))
            val diff = (1 shl (i + 1)) - remain
            if (right - left < diff)
                res = res or (1 shl i)
        }

        return res
    }
}

