class Solution {
    fun integerBreak(n: Int): Int {
        if (n < 4) return n - 1

        var res = 1
        var n2 = n
        while (n2 > 4) {
            res *= 3
            n2 -=3
        }

        res *= n2
        return res
    }
}

// Mathimatically solved O(1)
class Solution {
    fun integerBreak(n: Int): Int {
        if (n < 4) return n - 1

        var res = n / 3
        var rem = n % 3

        if (rem == 1) {
            rem = 4
            res--
        } else if (rem == 0) {
            rem = 1
        }

        return (Math.pow(3.toDouble(), res.toDouble()) * rem).toInt()
    }
}

