class Solution {
    fun decodeString(s: String): String {
        val stack = LinkedList<String>()

        for (c in s) {
            if (c != ']') {
                stack.addLast(c.toString())
            } else {
                val sb = StringBuilder()
                while (stack.isNotEmpty() && stack.peekLast() != "[")
                    sb.insert(0, stack.removeLast())
                stack.removeLast()

                val k = StringBuilder()
                while (stack.isNotEmpty() && stack.peekLast().all { char -> char.isDigit() })
                    k.insert(0, stack.removeLast())

                val times = k.toString().toInt()
                stack.addLast(sb.toString().repeat(times))
            }
        }

        return stack.joinToString("")
    }
}

class Solution {
    fun calcEquation(equations: List<List<String>>, values: DoubleArray, queries: List<List<String>>): DoubleArray {
        val adj = HashMap<String, ArrayList<Pair<String, Double>>>().apply {
            for (i in equations.indices) {
                val (a, b) = equations[i]
                val value = values[i]
                this[a] = getOrDefault(a, arrayListOf()).apply { add(b to value) }
                this[b] = getOrDefault(b, arrayListOf()).apply { add(a to (1.0 / value)) }
            }
        }

        fun bfs(
            start: String,
            end: String
        ): Double {
            if (start !in adj || end !in adj)
                return -1.0

            val visit = HashSet<String>()
            with (LinkedList<Pair<String, Double>>()) {
                addLast(start to 1.0)
                visit.add(start)

                while (isNotEmpty()) {
                    val (cur, totVal) = removeFirst()

                    if (cur == end) return totVal

                    adj[cur]?.forEach {
                        val (next, nextVal) = it
                        if (next !in visit) {
                            addLast(next to (totVal * nextVal))
                            visit.add(next)
                        }
                    }
                }
            }

            return -1.0
        }

        val res = DoubleArray(queries.size)
        for (i in queries.indices) {
            val (a, b) =  queries[i]
            res[i] = bfs(a, b)
        }

        return res
    }
}

class Solution {
    fun removeKdigits(num: String, k: Int): String {
        val stack = Stack<Char>() //monotonic stack
        var count = k
        for(i in 0 until num.length){
            while(count > 0 && !stack.isEmpty() && num[i] < stack.peek()){
                stack.pop() //remove the larger int
                count--
            }
            stack.push(num[i])
        }
        repeat(count){ //pop the last k integers (largest integers)
            stack.pop()
        }
        val sum = stack.joinToString("")
        return if(sum == "") "0" else sum.toBigInteger().toString() //to int to remove all leading Zeros, instead of using Strinbuilder
    }
}

class Solution {
    fun splitArray(nums: IntArray, k: Int): Int {

        fun canSplit(max: Int): Boolean {
            var subArrCnt = 1
            var curSum = 0
            for (n in nums) {
                curSum += n
                if (curSum > max) {
                    subArrCnt++
                    curSum = n
                }
            }
            return subArrCnt <= k
        }

        var l = nums.max()!!
        var r = nums.sum()!!
        var res = r
        while (l <= r) {
            val m = l + (r - l) / 2
            if (canSplit(m)) {
                res = m
                r = m - 1
            } else {
                l = m + 1
            }
        }

        return res
    }
}

class Solution {
    fun canPartition(nums: IntArray): Boolean {

        var sum = nums.sum()
        if(sum%2 != 0) return false // we cant divive an odd sum into 2 equal parts

        val dp = BooleanArray(sum+1)
        sum /= 2
        dp[0] = true

        for(num in nums){
            if(num > sum)
                return false
            for(i in sum downTo 0){
                if(i >= num)
                    dp[i] = dp[i] || dp[i-num]
            }
        }

        return dp[sum]
    }

}

class Solution {

    val dirs = arrayOf(intArrayOf(0,1),
                       intArrayOf(0,-1),
                       intArrayOf(1,0),
                       intArrayOf(-1,0))

    fun pacificAtlantic(grid: Array<IntArray>): List<List<Int>> {
        if(grid.size == 0) return emptyList()
        val result = mutableListOf<List<Int>>()

        val pacific = Array(grid.size) { BooleanArray(grid[0].size) }
        val atlantic = Array(grid.size) { BooleanArray(grid[0].size) }

        for(i in 0 until grid.size) {
            dfs(grid, Integer.MIN_VALUE, i, 0, pacific)
            dfs(grid, Integer.MIN_VALUE, i, grid[0].size - 1, atlantic)
        }

        for(i in 0 until grid[0].size) {
            dfs(grid, Integer.MIN_VALUE, 0, i, pacific)
            dfs(grid, Integer.MIN_VALUE, grid.size - 1, i, atlantic)
        }

        for(i in 0 until grid.size) {
            for(j in 0 until grid[0].size) {
                if(atlantic[i][j] && pacific[i][j]) result.add(listOf(i, j))
            }
        }

        return result
    }

    private fun dfs(grid: Array<IntArray>, height: Int, i: Int, j: Int, visited: Array<BooleanArray>) {
        if(i < 0 || i >= grid.size || j < 0 || j >= grid[0].size || grid[i][j] < height || visited[i][j]) return

        visited[i][j] = true

        dirs.forEach { dir ->
            dfs(grid, grid[i][j], dir[0] + i, dir[1] + j, visited)
        }
    }
}

class Solution {
    fun characterReplacement(s: String, k: Int): Int {
        val freq = IntArray(26);

        var res = 0
        var currMax = 0
        var start = 0

        for (end in 0..s.length-1) {
            val count = ++freq[s[end] - 'A']
            currMax = Math.max(currMax, count)

            if (end - start + 1 > currMax + k) {
                freq[s[start] - 'A']--
                start++
            }

            res = Math.max(res, end - start + 1)
        }

        return res
    }
}

/**
 * Definition for a QuadTree node.
 * class Node(var `val`: Boolean, var isLeaf: Boolean) {
 *     var topLeft: Node? = null
 *     var topRight: Node? = null
 *     var bottomLeft: Node? = null
 *     var bottomRight: Node? = null
 * }
 */

class Solution {
    fun construct(grid: Array<IntArray>): Node? {

        fun dfs(n: Int, r: Int, c: Int): Node? {
            var allSame = true

            for(i in 0 until n) {
                for(j in 0 until n) {
                    if(grid[r][c] != grid[r + i][c + j]) {
                        allSame = false
                        break
                    }
                }
            }

            if(allSame) return Node(if(grid[r][c] == 1) true else false, true)

            val nextN = n/2
            val topLeft = dfs(nextN, r, c)
            val topRight = dfs(nextN, r, c + nextN)
            val bottomLeft = dfs(nextN, r + nextN, c)
            val bottomRight = dfs(nextN, r + nextN, c + nextN)

            val node = Node(false, false)
            node.topLeft = topLeft
            node.topRight = topRight
            node.bottomLeft = bottomLeft
            node.bottomRight = bottomRight
            return node
        }

        return dfs(grid.size, 0, 0)
    }
}

