class Solution {
    fun findAllConcatenatedWordsInADict(words: Array<String>): List<String> {
        val wordSet = words.toSet()
        val dp = HashMap<String, Boolean>()

        fun dfs(word: String): Boolean {
            if (word in dp) return dp[word]!!
            for (i in 1 until word.length) {
                val prefix = word.substring(0, i)
                val suffix = word.substring(i, word.length)
                if ((prefix in wordSet && suffix in wordSet) ||
                    prefix in wordSet && dfs(suffix)) {
                        dp[word] = true
                        return true
                    }

            }

            dp[word] = false
            return false
        }

        var res = mutableListOf<String>()
        for (word in words) {
            if (dfs(word))
                res.add(word)
        }

        return res
    }
}

class Solution {
    fun makesquare(matchsticks: IntArray): Boolean {
        val length = matchsticks.sum()!! / 4
        val sides = IntArray (4)

        if (matchsticks.sum()!! / 4 != length) return false

        matchsticks.sortDescending()

        fun backtrack(i: Int): Boolean {
            if (i == matchsticks.size) return true

            for (j in 0..3) {
                if (sides[j] + matchsticks[i] <= length) {
                    sides[j] += matchsticks[i]
                    if (backtrack(i + 1))
                        return true
                    sides[j] -= matchsticks[i]
                }
            }

            return false
        }

        return backtrack(0)
    }
}

/*
* Recursion with memoization solution
*/
class Solution {
    fun findMaxForm(strs: Array<String>, m: Int, n: Int): Int {
        val dp = Array(m + 1){ Array(n + 1){ IntArray(strs.size){ -1 } } }

        fun dfs(i: Int, m: Int, n: Int): Int {
            if(i == strs.size) return 0

            if(dp[m][n][i] != -1) return dp[m][n][i]

            val zeros = strs[i].count{ it == '0' }
            val ones = strs[i].count{ it == '1' }

            dp[m][n][i] = dfs(i + 1, m, n)
            if(zeros <= m && ones <= n) {
                dp[m][n][i] = maxOf(
                    dp[m][n][i],
                    1 + dfs(i + 1, m - zeros, n - ones)
                )
            }

            return dp[m][n][i]
        }

        return dfs(0, m, n)
    }
}

/*
* DP solution
*/
class Solution {
    fun findMaxForm(strs: Array<String>, m: Int, n: Int): Int {
        val dp = Array(m + 1){ IntArray(n + 1) }

        for(str in strs) {
            val zeros = str.count{ it == '0'}
            val ones = str.count{ it == '1'}
            for(i in m downTo zeros) {
                for(j in n downTo ones) {
                    dp[i][j] = maxOf(
                        1 + dp[i - zeros][j - ones],
                        dp[i][j]
                    )
                }
            }
        }

        return dp[m][n]
    }
}

class Solution {
    fun findTargetSumWays(nums: IntArray, target: Int): Int {
        val memo = HashMap<String, Int>()

        fun dfs(i: Int, sum: Int): Int {
            if (i == nums.size)
                return if (sum == target) 1 else 0
            val key = "$i:$sum"
            if (key in memo)
                return memo[key]!!
            memo[key] = dfs(i + 1, sum + nums[i]) +
                dfs(i + 1, sum - nums[i])
            return memo[key]!!
        }

        return dfs(0, 0)
    }
}

class Solution {
    fun nextGreaterElement(nums1: IntArray, nums2: IntArray): IntArray {
        val res = IntArray(nums1.size){ -1 }

        val hm = HashMap<Int, Int>()
        for(i in 0 until nums1.size)
            hm[nums1[i]] = i

        val stack = ArrayDeque<Int>()
        for(current in nums2){
            while(stack.isNotEmpty() && current > stack.getLast()){
                val element = stack.removeLast()
                val index = hm[element]!!
                res[index] = current
            }
            if(current in hm)
                stack.addLast(current)
        }

        return res
    }
}

class Solution {
    fun findMaximizedCapital(k: Int, w: Int, profits: IntArray, capital: IntArray): Int {

        var totalCap = w
        // Pair of ("Profit" to "CapitalCost")
        val minCapital = PriorityQueue<Pair<Int, Int>> { a,b -> a.second - b.second }
        val maxProfit = PriorityQueue<Int> { a,b -> b - a }

        profits.zip(capital).forEach {
            minCapital.add(it.first to it.second)
        }

        repeat(k) exit@ {
            while(minCapital.isNotEmpty() && minCapital.peek().second <= totalCap) {
                val (prof, cap) = minCapital.poll()
                maxProfit.add(prof)
            }
            if(maxProfit.isEmpty()) return@exit
            totalCap += maxProfit.poll()
        }

        return totalCap
    }
}

