class Solution {
    fun change(amount: Int, coins: IntArray): Int {
        val cache = Array(coins.size) { IntArray(amount + 1) {-1} }

        fun dfs(i: Int, a: Int): Int {
            if (a == amount)
                return 1
            if (a > amount)
                return 0
            if (i == coins.size)
                return 0
            if (cache[i][a] != -1)
                return cache[i][a]

            cache[i][a] = dfs(i, a + coins[i]) + dfs(i + 1, a)

            return cache[i][a]
        }

        return dfs(0, 0)
    }
}

