        var prefix = 0
        nums.forEachIndexed {i, num ->
            prefix += num
            val remainder = prefix % k
            if(remainder !in hm) hm[remainder] = i
            else if(i - hm[remainder]!! >= 2) return true
        }
        return false
    }
}

class Solution {
