class Solution {
    fun leastInterval(tasks: CharArray, n: Int): Int {
        if(n == 0)
            return tasks.size
        val hm = HashMap<Char,Int>()
        for(task in tasks)
            hm[task] = hm.getOrDefault(task, 0) + 1
        val maxHeap = PriorityQueue<Int>(compareBy{-it})
        for(count in hm.values)
             maxHeap.add(count)
        val q = ArrayDeque<Pair<Int,Int>>() // time, value
        var time = 0
        while(!maxHeap.isEmpty() || !q.isEmpty()){
            if(!maxHeap.isEmpty()){
                var current = maxHeap.poll()
                current--
                if(current > 0)
                    q.add(Pair(time+n,current))
            }
            if(!q.isEmpty()){
                if(q.peek().first == time)
                    maxHeap.add(q.poll().second)
            }
            time++
        }
        return time
    }
}

class MyCircularQueue(val k: Int) {

    private data class ListNode<Int>(
        var value: Int, var next: ListNode<Int>? = null, var prev: ListNode<Int>? = null
    )

    private var left = ListNode(-1)
    private var right = ListNode(-1, null, left)
    private var space = k

    init {
        left.next = right
    }

    fun enQueue(element: Int): Boolean {
        if (isFull()) return false

        ListNode(element, right, right.prev).let { newNode ->
            right.prev!!.next = newNode
            right.prev = newNode
            space--
            return true
        }
    }

    fun deQueue(): Boolean {
        if (isEmpty()) return false

        left.next = left.next!!.next
        left.next!!.prev = left
        space++

        return true
    }

    fun Front() = left.next?.value ?: -1
    fun Rear() = right.prev?.value ?: -1

    fun isEmpty() = left.next == right
    fun isFull() = space == 0
}

// Bottom-up DP, Time O(n^2 * k) and Space O(n * k)
class Solution {
    fun kInversePairs(n: Int, k: Int): Int {
        val mod = 1_000_000_007
        val dp = Array (n + 1) { LongArray (k + 1) }

        dp[0][0] = 1
        for (i in 1..n) {
            for (j in 0..k) {
                for (p in 0 until i) {
                    if (j - p >= 0)
                        dp[i][j] = (dp[i][j] + dp[i - 1][j - p]) % mod
                }
            }
        }

        return dp[n][k].toInt()
    }
}

// Space optimized Bottom-up DP, Time O(n^2 * k) and Space O(k)
class Solution {
    fun kInversePairs(n: Int, k: Int): Int {
        val mod = 1_000_000_007
        var dp = LongArray (k + 1)

        dp[0] = 1
        for (i in 1..n) {
            val newDp = LongArray (k + 1)
            for (j in 0..k) {
                for (p in 0 until i) {
                    if (j - p >= 0)
                        newDp[j] = (newDp[j] + dp[j - p]) % mod
                }
            }
            dp = newDp
        }

        return dp[k].toInt()
    }
}

// Space optimized DP + Sliding window Time O(n * k) and Space O(k)
class Solution {
    fun kInversePairs(n: Int, k: Int): Int {
        val mod = 1_000_000_007
        var prev = LongArray (k + 1)

        prev[0] = 1
        for (i in 1..n) {
            val cur = LongArray (k + 1)
            var total = 0L
            for (j in 0..k) {
                if (j >= i)
                    total -= prev[j - i]
                total = (total + prev[j] + mod) % mod
                cur[j] = total
            }
            prev = cur
        }

        return prev[k].toInt()
    }
}

// O(n) time and O(1) space
class Solution {
    fun findErrorNums(nums: IntArray): IntArray {
        val n = nums.size

        var x = 0
        var y = 0
        for (i in 1..n) {
            x += nums[i - 1] - i
            y += nums[i - 1] * nums[i - 1] - i * i
        }

        var missing = (y - x * x) / (2 * x)
        var duplicate = missing + x

        return intArrayOf(duplicate, missing)
    }
}

