// Use XOR O(n) time and O(1) space
class Solution {
    fun findErrorNums(nums: IntArray): IntArray {
        val res = IntArray (2)

        for (i in nums.indices) {
            val num = Math.abs(nums[i])

            res[1] = res[1] xor ((i + 1) xor num)

            if (nums[num - 1] < 0) res[0] = num
            else nums[num - 1] *= -1
        }

        res[1] = res[1] xor res[0]
        return res
    }
}

