        val dp = IntArray (pairs.size) { -1 }

        fun dfs(i: Int): Int {
            if (i == pairs.size) return 0
            if (dp[i] != -1) return dp[i]

            var res = 1
            for (j in 0 until i) {
                if (pairs[i][0] > pairs[j][1])
                    res = maxOf(res, dfs(j) + 1)
            }

            dp[i] = res
            return res
        }

        var res = 1
        for (i in 0 until pairs.size)
            res = maxOf(res, dfs(i))

        return res
    }
}

