        var lisCount = 0
        for (i in nums.size-1 downTo 0) {
            var maxLen = 1
            var maxCount = 1

            for (j in i+1 until nums.size) {
                if (nums[i] < nums[j]) {
                    val curLen = lis[j]
                    val curCount = count[j]
                    if (curLen + 1 > maxLen) {
                        maxLen = curLen + 1
                        maxCount = curCount
                    } else if (curLen + 1 == maxLen) {
                        maxCount += curCount
                    }
                }
            }

            if (maxLen > lisLen) {
                lisLen = maxLen
                lisCount = maxCount
            } else if (maxLen == lisLen) {
                lisCount += maxCount
            }

            lis[i] = maxLen
            count[i] = maxCount
        }

        return lisCount
    }
