class Solution {
    fun validPalindrome(s: String): Boolean {

        var left = 0
        var right = s.lastIndex

        while (left <= right) {
            if(s[left] != s[right])
                return isValid(s, left, right -1) || isValid(s, left + 1, right)
            left++
            right--
        }

        return true
    }

    private fun isValid(s: String, _left: Int, _right: Int): Boolean {

        var left = _left
        var right = _right

        while (left <= right) {
            if(s[left] != s[right])
                return false
            left++
            right--
        }

        return true
    }
}

/*
* Using a stack. Time Complexity O(N) and Space Complexity O(N)
*/
class Solution {
    fun calPoints(operations: Array<String>): Int {

        val stack = ArrayDeque<Int>()

        for(op in operations) {
            when (op) {
                "+" -> {
                    val top = stack.removeLast()
                    val sum = stack.peekLast() + top
                    stack.addLast(top)
                    stack.addLast(sum)
                }
                "D" -> {
                    val top = stack.peekLast() * 2
                    stack.addLast(top)
                }
                "C" -> {
                    stack.removeLast()
                }
                else -> {
                    stack.addLast(op.toInt())
                }
            }
        }

        return stack.sum()
    }
}

class Solution {
    fun findRedundantConnection(edges: Array<IntArray>): IntArray {
        val uf = UnionFind(edges.size)

        for (edge in edges) {
            val (u, v) = edge

            if (uf.isConnected(u-1, v-1))
                return intArrayOf(u, v)

            uf.unify(u-1, v-1)
        }

        return intArrayOf(0)
    }
}

class UnionFind(n : Int) {
    val parent = IntArray(n) { it }
    val rank = IntArray(n) { 1 }

    fun unify(p: Int, q: Int) {
        val rootP = find(p)
        val rootQ = find(q)

        if (rootP == rootQ)
            return

        if (rank[rootP] > rank[rootQ]) {
            parent[rootQ] = parent[rootP]
            rank[rootP] += rank[rootQ]
        } else {
            parent[rootP] = parent[rootQ]
            rank[rootQ] += rank[rootP]
        }
    }

    fun find(p: Int): Int {
        var root = p
        var curr = p

        while (root != parent[root])
            root = parent[root]

        while (root != curr) {
            val next = parent[curr]
            parent[p] = parent[root]
            curr = next
        }

        return root
    }

    fun isConnected(p: Int, q: Int): Boolean {
        return find(p) == find(q)
    }
}

class Solution {
    fun minStickers(stickers: Array<String>, target: String): Int {
        val stickCount = HashMap<String, MutableMap<Char, Int>>().apply {
            stickers.forEach { s ->
                this[s] = s.groupingBy { it }
                    .eachCount()
                    .toMutableMap()
            }
        }

        val dp = HashMap<String, Int>()

        fun dfs(t: String, stick: MutableMap<Char, Int>): Int {
            dp[t]?.let {
                return it
            }

            var res = if (stick.isEmpty()) 0 else 1
            val remainT = StringBuilder()
            for (c in t) {
                if (c in stick && stick[c]!! > 0) {
                    stick[c] = stick[c]!! - 1
                } else {
                    remainT.append(c)
                }
            }

            if (remainT.length > 0) {
                val remainTS = remainT.toString()
                var used = Integer.MAX_VALUE
                for (s in stickCount.values) {
                    if (remainTS[0]!! !in s)
                        continue
                    used = minOf(used, dfs(remainTS, s.toMutableMap()))
                }

                dp[remainTS] = used
                res = if (used == Integer.MAX_VALUE ) Integer.MAX_VALUE else res + used
            }

            return res
        }


        val res = dfs(target, mutableMapOf<Char, Int>())
        return if (res == Integer.MAX_VALUE) -1 else res
    }
}

class Solution {
    fun maxAreaOfIsland(grid: Array<IntArray>): Int {
        var res = 0

        for (i in 0..grid.size-1) {
            for (j in 0..grid[0].size-1) {
                if (grid[i][j] == 1) {
                    val curr = dfs(grid, i, j)
                    res = Math.max(res, curr)
                }
            }
        }

        return res
    }

    fun dfs(grid: Array<IntArray>, row: Int, col: Int): Int {
        if (row < 0 || row >= grid.size || col < 0 || col >= grid[0].size)
            return 0

        if (grid[row][col] == 0)
            return 0

        grid[row][col] = 0

        return dfs(grid, row+1, col) + dfs(grid, row-1, col) + dfs(grid, row, col+1) + dfs(grid, row, col-1)+1
    }
}

class Solution {
    fun canPartitionKSubsets(nums: IntArray, k: Int): Boolean {

        var target = nums.sum()
        if(target%k != 0) return false // we cant divive nums equally by k
        target /= k


        val used = BooleanArray(nums.size)
        nums.sortDescending()

        fun backtrack(i: Int, k: Int, sum: Int): Boolean {

            if(k == 0) return true

            if(sum == target) return backtrack(0, k-1, 0)

            for(j in i until nums.size){
                if(nums[j] > target) return false
                if(used[j]==true || nums[j]+sum > target) continue
                used[j] = true
                if(backtrack(j+1, k, sum+nums[j]) == true) return true
                used[j] = false
            }

            return false
        }

        return backtrack(0,k,0)
    }
}

/**
 * Example:
 * var ti = TreeNode(5)
 * var v = ti.`val`
 * Definition for a binary tree node.
 * class TreeNode(var `val`: Int) {
 *     var left: TreeNode? = null
 *     var right: TreeNode? = null
 * }
 */

 // Recursive solution (Non self balancing)
class Solution {
    fun insertIntoBST(root: TreeNode?, value: Int): TreeNode? {

        root?: return TreeNode(value)

        if (value > root.value) root.right = insertIntoBST(root.right, value)
        else root.left = insertIntoBST(root.left, value)

        return root
    }

    private val TreeNode.value get() = `val`
}

// Iterative Solution (Non self balancing)
class Solution {
    fun insertIntoBST(root: TreeNode?, value: Int): TreeNode? {

        root?: return TreeNode(value)

        var current = root

        while (current != null) {
            if (value > current!!.value) {
                if (current.right != null){
                    current = current?.right
                } else {
                    current.right = TreeNode(value)
                    break
                }
            } else {
                if (current.left != null){
                    current = current?.left
                } else {
                    current.left = TreeNode(value)
                    break
                }
            }
        }

        return root
    }

    private val TreeNode.value get() = `val`
}

class KthLargest(val k: Int, val nums: IntArray) {
    val minHeap = PriorityQueue<Int>()

    init{
        for (num in nums)
            minHeap.add(num)
        while (minHeap.size > k)
            minHeap.poll()
    }

    fun add(`val`: Int): Int {
        minHeap.add(`val`)
        if (minHeap.size > k)
            minHeap.poll()
        return minHeap.peek()
    }

}

class Solution {
    fun search(nums: IntArray, target: Int): Int {
        return searchAux(nums, target, 0, nums.size - 1)
    }

    private fun searchAux(nums: IntArray, target: Int, begin: Int, end: Int): Int {
        if (begin > end) return -1

        val mid: Int = (begin + end) / 2

        return if (nums[mid] == target) mid
        else if (nums[mid] > target) searchAux(nums, target, begin, mid - 1)
        else searchAux(nums, target, mid + 1, end)
    }
}

