class Solution {
    fun splitListToParts(head: ListNode?, k: Int): Array<ListNode?> {
        var n = 0
        var cur = head
        while (cur != null) {
            cur = cur?.next
            n++
        }

        val len = n / k
        var rem = n % k

        cur = head
        val res = arrayOfNulls<ListNode?>(k)
        for (i in 0 until k) {
            res[i] = cur

            val end = (len - 1) + if (rem > 0) 1 else 0
            for (j in 0 until end) {
                cur?: break
                cur = cur?.next
            }

            if (rem > 0) rem--
            if (cur != null) {
                val temp = cur?.next
                cur.next = null
                cur = temp
            }
        }

        return res
    }
}

class Solution {
    fun asteroidCollision(ast: IntArray): IntArray {
        val stack = LinkedList<Int>()

        for (_a in ast) {
            var a = _a
            while (stack.isNotEmpty() && a < 0 && stack.peekLast() > 0) {
                val diff = a + stack.peekLast()
                if (diff < 0) {
                    stack.removeLast()
                } else if (diff > 0) {
                    a = 0
                } else {
                    a = 0
                    stack.removeLast()
                }
            }

            if (a != 0) stack.addLast(a)
        }

        return stack.toIntArray()
    }
}

