class Solution {
    fun dailyTemperatures(temperatures: IntArray): IntArray {
        if (temperatures.size == 1) return intArrayOf(0)
        val stack = Stack<Int>()
        val resultantArray = IntArray(temperatures.size)
        var poppedElement: Int
        for (i in 0..temperatures.lastIndex) {
            while (stack.isNotEmpty() && temperatures[stack.peek()] < temperatures[i]) {
                poppedElement = stack.pop()
                resultantArray[poppedElement] = i - poppedElement
            }
            stack.push(i)
        }
        return resultantArray
    }
}

class Solution {
    fun deleteAndEarn(nums: IntArray): Int {
        val count = HashMap<Int, Int>().apply {
            for (n in nums) this[n] = this.getOrDefault(n, 0) + 1
        }
        val noDups = nums.toSet().toTypedArray().apply { this.sort()}

        var before = 0
        var sum = 0
        for (i in noDups.indices) {
            val cur = noDups[i] * count[noDups[i]]!!
            if (i > 0 && noDups[i] == noDups[i - 1] + 1) {
                val temp = sum
                sum = maxOf(cur + before, sum)
                before = temp
            } else {
                val temp = sum
                sum = cur + sum
                before = temp
            }
        }

        return sum
    }
}

class Solution {
    //times[i] == [source, target, weight]
    fun networkDelayTime(times: Array<IntArray>, n: Int, k: Int): Int {
        val adjList = ArrayList<ArrayList<Pair<Int,Int>>>(times.size)
        for(i in 0..n)
            adjList.add(ArrayList<Pair<Int,Int>>())
        for(time in times){
            val (source, target, weight) = time
            adjList.get(source).add(Pair(target, weight))
        }
        //minheap stores [node, weight]
        val minHeap = PriorityQueue<IntArray>{ edge1: IntArray, edge2: IntArray ->
            edge1[1] - edge2[1]
        }
        val visited = HashSet<Int>()
        minHeap.add(intArrayOf(k,0))
        var time = 0 //the max of all the shortest paths
        while(!minHeap.isEmpty()){
            val (node, weight) = minHeap.poll()
            if(visited.contains(node))
                continue
            visited.add(node)
            time = maxOf(time, weight)
            val listofnodes = adjList.get(node)
            for(adjacent in listofnodes){
                val (adjNode, adjWeight) = adjacent
                if(!visited.contains(adjNode))
                    minHeap.add(intArrayOf(adjNode, adjWeight+weight)) // total path to each adjNode
            }
        }
        return if(visited.size == n) time else -1
    }
}

