class Solution {
    fun reorganizeString(s: String): String {
        val freq = IntArray (26).apply {
            for (c in s) this[c - 'a']++
        }

        var maxFreq = -1
        var maxChar = -1
        for (letter in 0..25) {
            if (freq[letter] > maxFreq) {
                maxFreq = freq[letter]
                maxChar = letter
            }
        }

        if (maxFreq > (s.length + 1) / 2) return ""

        var i = 0
        val res = CharArray (s.length).apply {
            while (freq[maxChar] > 0) {
                this[i] = 'a' + maxChar
                i += 2
                freq[maxChar]--
            }
        }

        for (letter in 0..25) {
            while (freq[letter] > 0) {
                if (i > s.lastIndex) i = 1
                res[i] = 'a' + letter
                i += 2
                freq[letter]--
            }
        }

        return res.joinToString("")
    }
}

class Solution {
    fun swimInWater(grid: Array<IntArray>): Int {
        val visited = Array<BooleanArray>(grid.size){ BooleanArray(grid[0].size) }
        val minHeap = PriorityQueue<IntArray>{ a: IntArray, b: IntArray -> a[0] - b[0] } //[height, r, c]
        val directions = arrayOf(intArrayOf(1,-1,0,0),intArrayOf(0,0,1,-1))
        minHeap.add(intArrayOf(grid[0][0],0,0)) //startpos
        while(!minHeap.isEmpty()){
            val (h,r,c) = minHeap.poll()
            visited[r][c] = true
            if(r == grid.size-1 && c == grid[0].size-1)
                return h
            for(i in 0..3){
                val nextR = r + directions[0][i]
                val nextC = c + directions[1][i]
                if(isValid(grid,visited,nextR, nextC))
                    minHeap.add(intArrayOf(maxOf(h,grid[nextR][nextC]),nextR,nextC))
            }
        }
        return -1
    }
    private fun isValid(
        grid: Array<IntArray>,
        visited: Array<BooleanArray>,
        r: Int,
        c: Int
    ) = r >= 0 && c >= 0 && r < grid.size && c < grid[0].size && visited[r][c] == false
}

class Solution {
    fun kthGrammar(n: Int, k: Int): Int {
        var cur = 0
        var left = 1
        var right = 2.0.pow(n - 1).toInt()

        repeat (n - 1) {
            val mid = (left + right) / 2
            if (k <= mid) {
                right = mid
            } else {
                left = mid + 1
                cur = if (cur == 1) 0 else 1
            }
        }

        return cur
    }
}

