 * Definition for a binary tree node.
 * class TreeNode(var `val`: Int) {
 *     var left: TreeNode? = null
 *     var right: TreeNode? = null
 * }
 */
class Solution {

    fun minDiffInBST(root: TreeNode?): Int {

        var res = Integer.MAX_VALUE
        var prev = -1 //Values in range (0 to 10^5)

        fun dfs(root: TreeNode?) {
            if(root == null) return

            dfs(root.left)
            if(prev != -1) res = minOf(res, root.value - prev)
            prev = root.value
            dfs(root.right)
        }

        dfs(root)
        return res
    }

    val TreeNode.value get() = this.`val`
}

class Solution {
    fun findCheapestPrice(n: Int, flights: Array<IntArray>, src: Int, dst: Int, k: Int): Int {
        var cost = IntArray(n){ Int.MAX_VALUE }
        cost[src] = 0

        for (i in 0..k) {
            val temp = cost.clone()

            for (flight in flights) {
                val (u, v, w) = flight

                if (cost[u] != Int.MAX_VALUE)
                    temp[v] = Math.min(temp[v], cost[u] + w)
            }

            cost = temp
        }

        return if (cost[dst] == Int.MAX_VALUE) -1 else cost[dst]
    }
}

class Solution {
    fun champagneTower(poured: Int, query_row: Int, query_glass: Int): Double {
        var prevRow = doubleArrayOf(poured.toDouble())

        for (row in 1..query_row) {
            var nextRow = DoubleArray (row + 1)
            for (i in 0 until row) {
                var leftOver = prevRow[i] - 1.0
                if (leftOver > 0) {
                    nextRow[i] += leftOver * 0.5
                    nextRow[i + 1] += leftOver * 0.5
                }
            }
            prevRow = nextRow
        }

        return minOf(1.0, prevRow[query_glass])
    }
}

class Solution {
    fun eventualSafeNodes(graph: Array<IntArray>): List<Int> {
        val resultantList = mutableListOf<Int>()
        // -1 -> non-safe node, 0 -> unknown, 1-> safe node
        val safeState = IntArray(graph.size)
        val visitedNode = hashSetOf<Int>()

        fun isSafe(currentNode: Int): Boolean {
            visitedNode.add(currentNode)
            for (adjacentNode in graph[currentNode]) {
                if (safeState[adjacentNode] == 1) continue
                if (
                    adjacentNode in visitedNode ||
                    safeState[adjacentNode] == -1 ||
                    !isSafe(adjacentNode)
                ) {
                    safeState[adjacentNode] = -1
                    safeState[currentNode] = -1
                    return false
                }
            }
            safeState[currentNode] = 1
            return true
        }

        for (node in graph.indices) {
            if (safeState[node] == -1) continue
            if (safeState[node] == 1 || isSafe(node)) resultantList.add(node)
        }
        return resultantList
    }
}

class Solution {
    fun new21Game(n: Int, k: Int, maxPts: Int): Double {
        if (k == 0 || k + maxPts <= n)
            return 1.0

        val dp = DoubleArray(k + maxPts)
        var windowSum = 0.0

        for (i in k until (k + maxPts))
            windowSum += if (i <= n) 1.0 else 0.0

        for (i in k - 1 downTo 0) {
            dp[i] = windowSum / maxPts
            windowSum += dp[i]
            if (i + maxPts <= n) {
                windowSum -= if (dp[i + maxPts] != 0.0) dp[i + maxPts] else 1.0
            }
        }

        return dp[0]
    }
}

class Solution {
    fun pushDominoes(d: String): String {
        val domArr = d.toCharArray()
        val q = LinkedList<Pair<Int, Char>>()

        for ((i, v) in domArr.withIndex()) {
            if (v != '.')
                q.addLast(i to v)
        }

        while (q.isNotEmpty()) {
            val (i, v) = q.removeFirst()
            if (v == 'L' && i > 0 && domArr[i - 1] == '.') {
                q.addLast(i - 1 to 'L')
                domArr[i - 1] = 'L'
            } else if (v == 'R') {
                if (i + 1 < domArr.size && domArr[i + 1] == '.') {
                    if (i + 2 < domArr.size && domArr[i + 2] == 'L') {
                        q.removeFirst()
                    } else {
                        q.addLast(i + 1 to 'R')
                        domArr[i + 1] = 'R'
                    }
                }
            }
        }

        return String(domArr)
    }
}

class Solution {
    fun isNStraightHand(hand: IntArray, groupSize: Int): Boolean {
        if (hand.size % groupSize != 0) return false
        val countMap = mutableMapOf<Int, Int>()
        hand.forEach { countMap[it] = countMap.getOrDefault(it, 0) + 1 }
        val minHeap = PriorityQueue(countMap.keys)

        while (minHeap.isNotEmpty()) {
            val minValue = minHeap.peek()
            if (countMap.getValue(minValue) == 0) {
                minHeap.remove()
                continue
            }
            // loop through consecutive numbers starting from the "minValue" number
            for (consecutiveNumber in minValue until (minValue + groupSize)) {
                if (
                    consecutiveNumber !in countMap.keys ||
                    countMap.getValue(consecutiveNumber) == 0
                ) return false
                countMap[consecutiveNumber] = countMap.getValue(consecutiveNumber) - 1
            }
            // if the loop successfully executes without returning, it indicates that
            // it was possible to create a group of size [groupSize] with minValue
            // as the first element in the group.
        }
        return true
    }
}

class Solution {
    fun carFleet(target: Int, position: IntArray, speed: IntArray): Int {
        val sortedPairs = position
            .zip(speed)
            .sortedBy { (position, _) -> position }
        var numberOfFleets = 1
        var timeRequiredForCarInFrontToReachInTarget =
            (target - sortedPairs[sortedPairs.lastIndex].first) / sortedPairs[sortedPairs.lastIndex].second.toFloat()
        var timeRequiredForCurrentCarToReachTarget: Float
        for (i in (sortedPairs.lastIndex - 1) downTo 0) {
            timeRequiredForCurrentCarToReachTarget = (target - sortedPairs[i].first) / sortedPairs[i].second.toFloat()
            if (timeRequiredForCurrentCarToReachTarget > timeRequiredForCarInFrontToReachInTarget) {
                // the current car requires more time to reach the destination
                // than the car in front of it.
                numberOfFleets++
                timeRequiredForCarInFrontToReachInTarget = timeRequiredForCurrentCarToReachTarget
            }
        }
        return numberOfFleets
    }
}

