class Solution {
    fun leafSimilar(root1: TreeNode?, root2: TreeNode?): Boolean {

        fun dfs(root: TreeNode?, res: MutableList<Int>) {
            root?: return

            if (root.left == null && root.right == null)
                res.add(root.`val`)

            dfs(root.left, res)
            dfs(root.right, res)
        }

        val res1: MutableList<Int> = mutableListOf()
        val res2: MutableList<Int> = mutableListOf()

        dfs(root1, res1)
        dfs(root2, res2)

        return res1 == res2
    }
}

class Solution {
    fun minEatingSpeed(piles: IntArray, h: Int): Int {
        var left = 1
        var right = 1

        for (pile in piles) {
            right = Math.max(right, pile)
        }

        while (left < right) {
            val mid = left + (right - left)/2

            if (canEat(piles, h, mid)) {
                right = mid
            } else {
                left = mid+1
            }
        }

        return left
    }

    fun canEat(piles: IntArray, h: Int, speed: Int): Boolean {
        var sum = 0

        for (pile in piles) {
            sum += Math.ceil(pile/speed.toDouble()).toInt()

            if (sum > h)
                return false
        }

        return true
    }
}

