class Solution {
    fun totalFruit(fruits: IntArray): Int {

        val baskets = HashMap<Int, Int>()
        var left = 0
        var right = 0
        var max = 0

        while (right < fruits.size) {

            baskets[fruits[right]] = baskets.getOrDefault(fruits[right], 0) + 1

            while (baskets.size > 2) {
                val fruit = fruits[left]
                baskets[fruit] = baskets.getOrDefault(fruit, 0) - 1
                left++

                if (baskets[fruit] == 0)
                    baskets.remove(fruit)
            }

            max = maxOf(max, right - left + 1)
            right++
        }

        return max
    }
}

class Solution {
    fun sortArrayByParity(nums: IntArray): IntArray {
        var odd = nums.lastIndex
        var i = 0

        while (i < odd) {
            if (nums[i] % 2 == 1) {
                val temp = nums[i]
                nums[i] = nums[odd]
                nums[odd] = temp
                odd--
            } else {
                i++
            }
        }

        return nums
    }
}

class Solution {
    fun sumSubarrayMins(_arr: IntArray): Int {
        val mod = 1_000_000_007
        var res = 0L
        val arr = intArrayOf(Integer.MIN_VALUE) + _arr + intArrayOf(Integer.MIN_VALUE)
        val stack = Stack<Pair<Int, Int>>()

        for ((i, n) in arr.withIndex()) {
            while (stack.isNotEmpty() && n < stack.peek().second) {
                val (j, m) = stack.pop()
                val left = if (stack.isNotEmpty()) j - stack.peek().first else j + 1
                val right = i - j
                res = (res + m.toLong() * left * right) % mod
            }
            stack.push(i to n)
        }

        return res.toInt()
    }
}

// Another and just a little different solution, you can also only push indices to the stack
class Solution {
    fun sumSubarrayMins(arr: IntArray): Int {
        val stack = LinkedList<Int>()
        val mod = 1_000_000_007
        var res = 0L

        for (right in 0..arr.size) {
            val curVal = if (right < arr.size) arr[right] else 0

            while (stack.isNotEmpty() && curVal < arr[stack.peekLast()]) {
                val cur = stack.removeLast()
                val left = stack.peekLast() ?: -1
                val noOfSubArrs = (cur.toLong() - left) * (right - cur)
                res = (res + noOfSubArrs * arr[cur]) % mod
            }

            stack.addLast(right)
        }

        return res.toInt()
    }
}

class Solution {
    fun snakesAndLadders(board: Array<IntArray>): Int {
        val len = board.size
        board.reverse()

        fun intToPos(square: Int): Pair<Int, Int> {
            val r = (square - 1) / len
            var c = (square - 1) % len
            if (r % 2 == 1)
                c = len - 1 - c
            return r to c
        }

        val q = LinkedList<Pair<Int, Int>>()
        q.addFirst(1 to 0)
        val visited = HashSet<Int>()
        while (q.isNotEmpty()) {
            val (square, moves) = q.removeLast()

            for (i in 1..6) {
                var next = i + square
                val (r, c) = intToPos(next)
                if (board[r][c] != -1)
                    next = board[r][c]
                if (next == len * len)
                    return moves + 1
                if (next !in visited) {
                    visited.add(next)
                    q.addFirst(next to moves + 1)
                }

            }
        }

        return -1
    }
}

class Solution {
    fun maxSubarraySumCircular(nums: IntArray): Int {
        if (nums.size == 1) return nums[0]
        // max sum
        var totalSum = nums[0]
        var maxSum = nums[0]
        var currentMaxSum = nums[0]
        // minSum
        var minSum = nums[0]
        var currentMinSum = nums[0]
        for (i in 1..nums.lastIndex) {
            // max sum computation
            currentMaxSum = maxOf(nums[i], currentMaxSum + nums[i])
            maxSum = maxOf(maxSum, currentMaxSum)
            // minSum computation
            currentMinSum = minOf(nums[i], currentMinSum + nums[i])
            minSum = minOf(minSum, currentMinSum)
            totalSum += nums[i]
        }
        return if (minSum != totalSum) maxOf((totalSum - minSum), maxSum) else maxSum
    }
}

class Solution {
    fun numMusicPlaylists(n: Int, goal: Int, k: Int): Int {
        val cache = Array (n + 1) { LongArray (goal + 1) { -1 } }
        val mod = 1000000007

        fun count(song: Int, left: Int): Long {
            if (left == 0)
                return if (song == n) 1L else 0L
            if (cache[song][left] != -1L) return cache[song][left]

            var res = 0L
            if (song + 1 <= n)
                res += (n - song) * count(song + 1, left - 1)
            if (song - k > 0)
                res += (song - k) * count(song, left - 1)

            cache[song][left] = res % mod
            return cache[song][left]
        }

        return count(0, goal).toInt()
    }
}

