class Solution {
    fun isCompleteTree(root: TreeNode?): Boolean {

        val q = LinkedList<TreeNode?>().apply{
            this.addFirst(root)
        }

        while(q.isNotEmpty()) {
            val node = q.removeLast()

            if(node != null) {
                q.addFirst(node.left)
                q.addFirst(node.right)
            } else {
                while(q.isNotEmpty()) {
                    if(q.removeLast() != null)
                        return false
                }
            }
        }

        return true
    }
}

class Solution {
    fun sortedSquares(nums: IntArray): IntArray {
        var left = 0; var right = nums.size-1; var end = nums.size-1
        val rArray = IntArray(nums.size)
        while(left <= right){ // or while(end >= 0)
            val ls = nums[left] * nums[left]
            val rs = nums[right] * nums[right]
            if(ls > rs){
                rArray[end] = ls
                left++
            }else{
                //rs > ls
                rArray[end] = rs
                right--
            }
            end--
        }
        return rArray
    }
}

class Solution {
    fun maxTurbulenceSize(arr: IntArray): Int {
        if (arr.size == 1) return 1
        var previousEqualitySymbol = ' '
        var currentSubArraySize = 1
        var maxSubArraySize = 1
        for (i in 1..arr.lastIndex) {
            if (arr[i - 1] > arr[i] && previousEqualitySymbol != '>') {
                currentSubArraySize++
                maxSubArraySize = maxOf(maxSubArraySize, currentSubArraySize)
                previousEqualitySymbol = '>'
                continue
            }
            if (arr[i - 1] < arr[i] && previousEqualitySymbol != '<') {
                currentSubArraySize++
                maxSubArraySize = maxOf(maxSubArraySize, currentSubArraySize)
                previousEqualitySymbol = '<'
                continue
            }
            currentSubArraySize = if (arr[i - 1] == arr[i]) 1 else 2
            maxSubArraySize = maxOf(maxSubArraySize, currentSubArraySize)
            previousEqualitySymbol = when {
                arr[i - 1] < arr[i] -> '<'
                arr[i - 1] > arr[i] -> '>'
                else -> ' '
            }
        }
        return maxSubArraySize
    }
}

class TimeMap {
    private data class TimeStampValuePair(
        val timestamp: Int,
        val value: String
    )

    private val keyMap = mutableMapOf<String, MutableList<TimeStampValuePair>>()

    fun set(key: String, value: String, timestamp: Int) {
        keyMap.getOrPut(key, ::mutableListOf).add(TimeStampValuePair(timestamp, value))
    }

    fun get(key: String, timestamp: Int): String {
        if (key !in keyMap.keys) return ""
        val searchList = keyMap.getValue(key)
        if (searchList.isEmpty()) return ""
        return binarySearch(
            list = searchList,
            targetTimeStamp = timestamp
        )
    }

    private fun binarySearch(
        list: List<TimeStampValuePair>,
        targetTimeStamp: Int
    ): String {
        if (list.first().timestamp > targetTimeStamp) return ""
        if (list.last().timestamp < targetTimeStamp) return list.last().value
        var startIndex = 0
        var endIndex = list.lastIndex
        var midIndex: Int
        var result = ""
        while (startIndex <= endIndex) {
            midIndex = startIndex + (endIndex - startIndex) / 2
            when {
                list[midIndex].timestamp <= targetTimeStamp -> {
                    if (list[midIndex].timestamp == targetTimeStamp) return list[midIndex].value
                    result = list[midIndex].value
                    startIndex = midIndex + 1
                }

                else -> endIndex = midIndex - 1
            }
        }
        return result
    }
}

