class Solution {

    fun mincostTickets(days: IntArray, costs: IntArray): Int {
        val dp = mutableMapOf<Int, Int>()

        for (dayIndex in days.indices.reversed()) {
            dp[dayIndex] = Int.MAX_VALUE

            for ((daysCount, cost) in intArrayOf(1, 7, 30).zip(costs)) {
                var nextDayIndex = dayIndex
                while (nextDayIndex < days.size && days[nextDayIndex] < days[dayIndex] + daysCount)
                    nextDayIndex++

                dp[dayIndex] = min(dp[dayIndex]!!, cost + dp.getOrDefault(nextDayIndex, 0))
            }
        }

        return dp[0]!!
    }
}

class Solution {
    fun addToArrayForm(num: IntArray, k: Int): List<Int> {
        var carry = 0
        var toAdd = k
        val res = ArrayList<Int>()
        var pointer = num.size-1
        while(pointer >= 0 || toAdd > 0 || carry != 0) {
            val rightMostMask = toAdd % 10
            var temp = rightMostMask + carry
            if(pointer >= 0)
                temp += num[pointer]
            carry = 0
            if(temp >= 10){
                temp = temp % 10
                carry = 1
            }
            res.add(0, temp)
            toAdd = toAdd / 10
            pointer--
        }
        return res
    }
}

class Solution {
    fun subarraysWithKDistinct(nums: IntArray, k: Int): Int {
        val count = HashMap<Int, Int>()
        var res = 0

        var l = 0
        var m = 0
        for (r in 0 until nums.size) {
            count[nums[r]] = (count[nums[r]] ?: 0) + 1

            while (count.size > k) {
                count[nums[m]] = (count[nums[m]] ?: 0) - 1
                if ((count[nums[m]] ?: 0) == 0) count.remove(nums[m])
                m++
                l = m
            }

            while ((count[nums[m]] ?: 0) > 1) {
                count[nums[m]] = (count[nums[m]] ?: 0) - 1
                m++
            }

            if (count.size == k) res += (m - l + 1)
        }

        return res
    }
}

class Solution {
    fun orangesRotting(grid: Array<IntArray>): Int {
        val m = grid.size
        val n = grid[0].size
        var fresh = 0
        var minute = -1
        var queue = LinkedList<IntArray>()
        val dirs = arrayOf(intArrayOf(-1,0),intArrayOf(1,0),intArrayOf(0,1),intArrayOf(0,-1))

        for (i in 0..m-1) {
            for (j in 0..n-1) {
                val curr = grid[i][j]

                if (curr == 2)
                    queue.add(intArrayOf(i, j))
                else if (curr == 1)
                    fresh++
            }
        }

        var temp = LinkedList<IntArray>()

        while (queue.size != 0) {
            val curr = queue.poll()

            for (dir in dirs) {
                val x = curr[0] + dir[0]
                val y = curr[1] + dir[1]

                if (x < 0 || x >= m || y < 0 || y >= n)
                    continue

                if (grid[x][y] == 1) {
                    temp.add(intArrayOf(x, y))
                    fresh--
                    grid[x][y] = 2
                }
            }

            if (queue.size == 0) {
                minute++
                queue = temp
                temp = LinkedList<IntArray>()
            }
        }

        if (fresh != 0)
            return -1

        return if (minute == -1) 0 else minute
    }
}

class Solution {
    fun findJudge(n: Int, trust: Array<IntArray>): Int {
        val delta = IntArray (n + 1)

        for ((src, dst) in trust) {
           delta[dst]++
           delta[src]--
        }

        for (i in 1..n) {
            if (delta[i] == n - 1)
                return i
        }

        return -1
    }
}

class Solution {
    fun shipWithinDays(weights: IntArray, days: Int): Int {

        var left = Integer.MIN_VALUE
        var right = 0

        for(w in weights) {
            left = maxOf(left, w)
            right += w
        }

        fun canShip(cap: Int): Boolean {
            var currentCap = cap
            var ships = 1
            for(w in weights) {
                if(currentCap - w < 0){
                    ships++
                    currentCap = cap
                }
                currentCap -= w
            }
            return ships <= days
        }

        while(left <= right) {
            val mid = (left + right) / 2
            if(canShip(mid))
                right = mid - 1
            else
                left = mid + 1
        }

        return left
    }
}

class Solution {
    fun numEnclaves(grid: Array<IntArray>): Int {
        val rows = grid.size
        val cols = grid[0].size
        val dirs = arrayOf(
            intArrayOf(1, 0),
            intArrayOf(-1, 0),
            intArrayOf(0, 1),
            intArrayOf(0, -1)
        )

        val visited = Array(rows){BooleanArray(cols)}

        fun isValid(r: Int, c: Int) =
            r in (0 until rows) &&
            c in (0 until cols) &&
            visited[r][c] == false &&
            grid[r][c] == 1

        fun isValidBorder(r: Int, c: Int) =
            (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) &&
            visited[r][c] == false

        fun dfs(r: Int, c: Int): Int {
            if (!isValid(r, c))
                return 0

            visited[r][c] = true

            var res = 1
            for ((dr, dc) in dirs) {
                res += dfs(r + dr, c + dc)
            }

            return res
        }

        var totalLand = 0
        var borderLand = 0
        for (r in 0 until rows) {
            for (c in 0 until cols) {
                totalLand += grid[r][c]
                if (grid[r][c] == 1 && isValidBorder(r, c)) {
                    borderLand += dfs(r, c)
                }
            }
        }

        return totalLand - borderLand
    }

}

class Solution {
    fun twoCitySchedCost(costs: Array<IntArray>): Int {
        val diffs = mutableListOf<IntArray>().apply {
            costs.forEach { (c1, c2) ->
                add(intArrayOf(c2 - c1, c1, c2))
            }
        }
        .sortedWith(compareBy { it[0] })

        var res = 0
        val k = diffs.size / 2
        return diffs.withIndex()
            .sumBy { (i, a) -> if (i < k) a[2] else a[1] }
    }
}

class Solution {
    fun isRobotBounded(instructions: String): Boolean {
        var dirX = 0
        var dirY = 1
        var x = 0
        var y = 0

        for (d in instructions) {
            if (d == 'G') {
                x += dirX
                y += dirY
            } else if (d == 'L') {
                dirX = -1 * dirY.also { dirY = dirX }
            } else {
                dirX = dirY.also { dirY = -1 * dirX }
            }
        }

        return (x to y) == (0 to 0) || (dirX to dirY) != (0 to 1)
    }
}

// Dp solution
class Solution {
    fun maxSumAfterPartitioning(arr: IntArray, k: Int): Int {
        val n = arr.size
        val dp = IntArray (k)
        dp[0] = arr[0]

        for (i in 1 until n) {
            var curMax = 0
            var maxAtI = 0
            for (j in i downTo (i - k + 1)) {
                if (j < 0) break

                curMax = maxOf(curMax, arr[j])

                val winLen = i - j + 1
                val curSum = curMax * winLen
                val subArrSum = if (j > 0) dp[(j - 1) % k] else dp[k - 1]

                maxAtI = maxOf(maxAtI, curSum + subArrSum)
            }

            dp[i % k] = maxAtI
        }

        return dp[(n - 1) % k]
    }
}

// recursion + memoization
class Solution {
    fun maxSumAfterPartitioning(arr: IntArray, k: Int): Int {
        val n = arr.size
        val dp = IntArray (n) { -1 }

        fun dfs(i: Int): Int {
            if (i == n) return 0
            if (dp[i] != -1) return dp[i]

            var curMax = 0
            var res = 0
            for (j in i until minOf(n, i + k)) {
                curMax = maxOf(curMax, arr[j])
                val winLen = j - i + 1
                res = maxOf(
                    res,
                    dfs(j + 1) + curMax * winLen
                )
            }

            dp[i] = res
            return res
        }

        return dfs(0)
    }
}

class Solution {
    fun lastStoneWeight(stones: IntArray): Int {
        val heap = PriorityQueue<Int>{a, b -> b-a}

        stones.forEach{ stone ->
            heap.add(stone)
        }

        while (!heap.isEmpty()) {
            if (heap.size == 1)
                return heap.poll()

            val first = heap.poll()
            val sec = heap.poll()

            if (first != sec) {
                heap.add(first - sec)
            }
        }

        return 0
    }
}

