class Solution {
    fun numSubmatrixSumTarget(matrix: Array<IntArray>, target: Int): Int {
        val n = matrix.size
        val m = matrix[0].size
        val prefix = Array (n) { IntArray (m) }

        for (i in 0 until n) {
            for (j in 0 until m) {
                val top = if (i > 0) prefix[i - 1][j] else 0
                val left = if (j > 0) prefix[i][j - 1] else 0
                val topLeft = if (minOf(i, j) > 0) prefix[i - 1][j - 1] else 0
                prefix[i][j] = matrix[i][j] + top + left - topLeft
            }
        }

        var res = 0
        for (i in 0 until n) {
            for (i2 in i until n) {
                var count = HashMap<Int, Int>()
                count[0] = 1
                for (j in 0 until m) {
                    val curSum = prefix[i2][j] - (if (i > 0) prefix[i - 1][j] else 0)
                    val diff = curSum - target
                    res += (count[diff] ?: 0)
                    count[curSum] = (count[curSum] ?: 0) + 1
                }
            }
        }

        return res
    }
}

class Solution {
    fun shortestPathBinaryMatrix(grid: Array<IntArray>): Int {

        if(grid[0][0] == 1 || grid[grid.lastIndex][grid.lastIndex] == 1) return -1

        fun isValid(i: Int, j: Int) = i in (0..grid.lastIndex) && j in (0..grid.lastIndex) && grid[i][j] == 0

        val q = ArrayDeque<Pair<Int, Int>>()
        var distance = 0

        q.add(0 to 0)
        grid[0][0] = 1

        while (q.isNotEmpty()) {
            distance++
            val size = q.size
            repeat (size) {
                val (i, j) = q.poll()
                if(i == grid.lastIndex && j == grid.lastIndex) return distance
                for(cell in cells) {
                    val nextI = i + cell[0]
                    val nextJ = j + cell[1]
                    if(isValid(nextI, nextJ)) {
                        q.add(nextI to nextJ)
                        grid[nextI][nextJ] = 1
                    }
                }
            }
        }

        return -1
    }

    companion object {
        val cells = arrayOf(
            intArrayOf(0,1),
            intArrayOf(1,1),
            intArrayOf(0,-1),
            intArrayOf(1,-1),
            intArrayOf(1,0),
            intArrayOf(-1,-1),
            intArrayOf(-1,0),
            intArrayOf(-1, 1)
        )
    }
}

class Solution {
