        val stops = IntArray (1001)
        for ((pas, pick, drop) in trips) {
            stops[pick] += pas
            stops[drop] -= pas
        }

        var pas = 0
        for (i in 0..1000) {
            pas += stops[i]
            if (pas > capacity)
                return false
        }

        return true
    }
}

class Solution {
    fun findInMountainArray(target: Int, mountainArr: MountainArray): Int {
        var l = 1
        var r = mountainArr.length() - 2
        var peak = -1
        while (l <= r) {
            val m = (l + r) / 2
            val left = mountainArr.get(m - 1)
            val mid = mountainArr.get(m)
            val right = mountainArr.get(m + 1)

            if (left < mid && mid < right) {
                l = m + 1
            } else if (left > mid && mid > right) {
                r = m - 1
            } else {
                peak = m
                break
            }
        }

        l = 0
        r = peak
        while (l <= r) {
            val m = (l + r) / 2
            val value = mountainArr.get(m)
            if (value < target)
                l = m + 1
            else if (value > target)
                r = m - 1
            else
                return m
        }

        l = peak
        r = mountainArr.length() - 1
        while (l <= r) {
            val m = (l + r) / 2
            val value = mountainArr.get(m)
            if (value < target)
                r = m - 1
            else if (value > target)
                l = m + 1
            else
                return m
        }

        return -1
    }
}

class Solution {
    fun shortestAlternatingPaths(n: Int, redEdges: Array<IntArray>, blueEdges: Array<IntArray>): IntArray {
        val redAdj = Array(n) { ArrayList<Int>() }
        val blueAdj = Array(n) { ArrayList<Int>() }
        val redVisit = HashSet<Int>()
        val blueVisit = HashSet<Int>()

        for ((from, to) in redEdges) redAdj[from].add(to)
        for ((from, to) in blueEdges) blueAdj[from].add(to)

        val res = IntArray(n) { -1 }

        with (LinkedList<Pair<Int, Int>>()) {
            addFirst(0 to 0)

            var len = 0
            while (isNotEmpty()) {
                repeat (size) {
                    val (node, c) = removeLast()
                    if (res[node] == -1) res[node] = len

                    if (c != -1) {
                        redAdj[node].forEach {
                            if (it !in redVisit) {
                                addFirst(it to -1)
                                redVisit.add(it)
                            }
                        }
                    }

                    if (c != 1) {
                        blueAdj[node].forEach {
                            if (it !in blueVisit) {
                                addFirst(it to 1)
                                blueVisit.add(it)
                            }
                        }
                    }
                }

                len++
            }
        }

        return res
    }
}

