class Solution {
    fun stoneGameII(piles: IntArray): Int {
        val dp = Array (2) { Array (piles.size) { IntArray (piles.size + 1) } }

        fun bfs(a: Int, i: Int, m: Int): Int {
            if (i == piles.size)
                return 0
            if (dp[a][i][m] != 0)
                return dp[a][i][m]

            var res = if (a == 0) 0 else Integer.MAX_VALUE
            var total = 0
            for (x in 1..(2 * m)) {
                if (i + x > piles.size)
                    break
                total += piles[i + x - 1]
                if (a == 0)
                    res = maxOf(res, total + bfs(1, i + x, maxOf(m, x)))
                else
                    res = minOf(res, bfs(0, i + x, maxOf(m, x)))
            }

            dp[a][i][m] = res
            return dp[a][i][m]
        }

        return bfs(0, 0, 1)
    }
}

class Solution {
    fun longestCommonSubsequence(text1: String, text2: String): Int {
        if (text1.isEmpty() || text2.isEmpty()) {
            return 0
        }

        val M = text1.length
        val N = text2.length

        val dp = Array(M + 1){IntArray(N + 1){0}}

        for (i in 1..M) {
            for (j in 1..N) {
                if (text1[i - 1] == text2[j - 1]) {
                    dp[i][j] = dp[i - 1][j - 1] + 1
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                }
            }
        }
        return dp[M][N]
    }
}

// dp, space complexity down from O(n * t) down to O(t)
class Solution {
    fun numRollsToTarget(n: Int, k: Int, t: Int): Int {
        val mod = 1_000_000_007
        var dp = LongArray (t + 1)

        dp[0] = 1

        for (d in 0 until n) {
            val nextDp = LongArray (t + 1)
            for (m in 1..k) {
                for (s in m..t)
                    nextDp[s] = (nextDp[s] + dp[s - m]) % mod
            }
            dp = nextDp
        }

        return dp[t].toInt()
    }
}

// recursion + memo
class Solution {
    fun numRollsToTarget(n: Int, k: Int, t: Int): Int {
        val mod = 1_000_000_007
        val dp = Array (n + 1) { LongArray (t + 1) { -1L } }

        fun dfs(n: Int, s: Int): Long {
            if (n < 0 || s > t) return 0
            if (s == t && n == 0) return 1
            if (dp[n][s] != -1L) return dp[n][s]

            var res = 0L
            for (m in 1..k)
                res = (res + dfs(n - 1, s + m)) % mod

            dp[n][s] = res
            return dp[n][s]
        }

        return (dfs(n, 0) % mod).toInt()
    }
}

class Solution {
    fun countCharacters(words: Array<String>, chars: String): Int {
        val charMap = chars.groupingBy { it }.eachCount()
        var res = 0
        outer@for (word in words) {
            val wordMap = word.groupingBy { it }.eachCount()
            for ((ch, cnt) in wordMap) {
                if (charMap[ch] == null || charMap[ch]!! < cnt)
                    continue@outer
            }
            res += word.length
        }
        return res
    }
}

