class Solution {
    fun removeDuplicates(s: String, k: Int): String {
        val stack = LinkedList<Pair<Char, Int>>()

        for (c in s) {
            if (stack.isNotEmpty() && stack.peekLast().first == c) {
                val (ch, co) = stack.removeLast()
                stack.addLast(c to (co + 1))
            } else {
                stack.addLast(c to 1)
            }

            if (stack.isNotEmpty() && stack.peekLast().second == k) {
                stack.removeLast()
            }
        }

        val res = StringBuilder()
        for ((ch, co) in stack) {
            repeat (co) {
                res.append(ch)
            }
        }

        return res.toString()
    }
}

//DP with O(1) space complexity
class Solution {
    fun countVowelPermutation(n: Int): Int {
        val mod = 1_000_000_000 + 7
        var prev = LongArray (5) { 1L }

        val a = 0
        val e = 1
        val i = 2
        val o = 3
        val u = 4

        for (j in 1 until n) {
            val new = LongArray (5)
            new[a] = 0L + (prev[e] + prev[i] + prev[u]) % mod
            new[e] = 0L + (prev[a] + prev[i]) % mod
            new[i] = 0L + (prev[e] + prev[o]) % mod
            new[o] = 0L + (prev[i]) % mod
            new[u] = 0L + (prev[i] + prev[o]) % mod
            prev = new
        }

        return (prev.sum()!! % mod).toInt()
    }
}

//DP with O(n) space complexity
class Solution {
    fun countVowelPermutation(n: Int): Int {
        val mod = 1_000_000_000 + 7
        val dp = Array (n + 1) { LongArray (5) }

        for (j in 0 until 5)
            dp[1][j] = 1

        val a = 0
        val e = 1
        val i = 2
        val o = 3
        val u = 4

        for (j in 2..n) {
            dp[j][a] = 0L + (dp[j - 1][e] + dp[j - 1][i] + dp[j - 1][u]) % mod
            dp[j][e] = 0L + (dp[j - 1][a] + dp[j - 1][i]) % mod
            dp[j][i] = 0L + (dp[j - 1][e] + dp[j - 1][o]) % mod
            dp[j][o] = 0L + (dp[j - 1][i]) % mod
            dp[j][u] = 0L + (dp[j - 1][i] + dp[j - 1][o]) % mod
        }

        return (dp[n].sum()!! % mod).toInt()
    }
}

//recursion + memoization
class Solution {
    fun countVowelPermutation(n: Int): Int {
        val mod = 1_000_000_000 + 7
        val dp = Array (n) { IntArray (5) { -1 } }

        val a = 0
        val e = 1
        val i = 2
        val o = 3
        val u = 4

        val follow = mapOf(
            a to listOf(e),
            e to listOf(a, i),
            i to listOf(a, e, o, u),
            o to listOf(i, u),
            u to listOf(a)
        )

        fun dfs(idx: Int, prev: Int): Int {
            if (idx == n) return 1
            if (dp[idx][prev] != -1) return dp[idx][prev]

            var res = 0
            follow[prev]?.forEach {
                res = (res + dfs(idx + 1, it)) % mod
            }

            dp[idx][prev] = res
            return res
        }

        var res = 0
        follow.keys.forEach {
            res = (res + dfs(1, it)) % mod
        }

        return res
    }
}

class Solution {
    fun maxLength(arr: List<String>): Int {
        val charSet = HashSet<Char>()

        fun overlap(s: String): Boolean {
            val count = IntArray (26)

            for (c in s) count[c - 'a']++
            for (c in charSet) count[c - 'a']++

            return count.any { it > 1 }
        }

        fun backtrack(i: Int): Int {
            if (i == arr.size)
                return charSet.size

            var res = 0
            if (!overlap(arr[i])) {
                for (c in arr[i])
                    charSet.add(c)
                res = backtrack(i + 1)
                for (c in arr[i])
                    charSet.remove(c)
            }

            return maxOf(res, backtrack(i + 1))
        }

        return backtrack(0)
    }
}

class Solution {
    fun closedIsland(grid: Array<IntArray>): Int {
        val rows = grid.size
        val cols = grid[0].size

        val visited = Array(rows){BooleanArray(cols)}

        fun isValid(r: Int, c: Int) = r in (0 until rows) && c in (0 until cols)

        fun dfs(r: Int, c: Int): Int {
            if(!isValid(r, c))
                return 0
            if(grid[r][c] == 1 || visited[r][c] == true)
                return 1

            visited[r][c] = true
            return minOf(
                minOf(
                    dfs(r + 1, c),
                    dfs(r - 1, c)
                ),
                minOf(
                    dfs(r, c + 1),
                    dfs(r, c - 1)
                )
            )
        }

        var islands = 0
        for (r in 0 until rows) {
            for (c in 0 until cols) {
                if (grid[r][c] == 0 && visited[r][c] == false) {
                    if (dfs(r, c) != 0)
                        islands++
                }
            }
        }

        return islands
    }
}

class Solution {
    fun shiftGrid(grid: Array<IntArray>, k: Int): List<List<Int>> {
        val m = grid.size
        val n = grid[0].size

        fun posToVal(r: Int, c: Int) = r * n + c

        fun valToPos(v: Int) = (v / n) to (v % n)

        val res = MutableList<MutableList<Int>> (m) { MutableList<Int> (n) { 0 } }
        for (r in 0 until m) {
            for (c in 0 until n) {
                val newVal = (posToVal(r, c) + k) % (m * n)
                val (newR, newC) = valToPos(newVal)
                res[newR][newC] = grid[r][c]
            }
        }

        return res
    }
}

class Solution {
    fun suggestedProducts(products: Array<String>, searchWord: String): List<List<String>> {
        var res = mutableListOf<MutableList<String>>()
        products.sort()

        var l = 0
        var r = products.lastIndex
        for ((i, c) in searchWord.withIndex()) {
            while (l <= r && (products[l].length <= i || products[l][i] != c))
                l++
            while (l <= r && (products[r].length <= i || products[r][i] != c))
                r--

            var temp = mutableListOf<String>()
            val rem = r - l + 1
            for (j in 0 until minOf(3, rem))
                temp.add(products[l + j])
            res.add(temp)
        }

        return res
    }
}

// Optimized DP solution Time O(minOf(steps, arrLen)^2, and space optimized down from O(minOf(steps, arrLen)^2) to O(minOf(steps, arrLen))
class Solution {
    fun numWays(steps: Int, _arrLen: Int): Int {
        val mod = 1_000_000_000 + 7
        val arrLen = minOf(steps, _arrLen)
        var dp = IntArray (arrLen)

        dp[0] = 1

        for (step in 1..steps) {
            val nextDp = IntArray (arrLen)
            for (i in 0 until arrLen) {
                nextDp[i] = dp[i]
                if (i > 0)
                    nextDp[i] = (nextDp[i] + dp[i - 1]) % mod
                if (i < arrLen - 1)
                    nextDp[i] = (nextDp[i] + dp[i + 1]) % mod
            }
            dp = nextDp
        }

        return dp[0]
    }
}

/* Recursion + memoization, Time O(minOf(steps, arrLen)^2 and space O(minOf(steps, arrLen)^2
 * Here we use arrays for memoization, however, we set the 2D array's size to [steps + 1][steps + 1] because:
* 1) we can never move more than "steps" amount to the right, and we have constraints 1 <= steps <= 500 and 1 <= arrLen <= 10^6,
* so we can therefor make an optimization since we dont need all that extra space, and 2) it will not AC on Leetcode since they are looking for this optimisation.
*/
class Solution {
    fun numWays(steps: Int, arrLen: Int): Int {
        val mod = 1_000_000_000 + 7
        val dp = Array (steps + 1) { IntArray (steps + 1) { -1 } }

        fun dfs(i: Int, left: Int): Int {
            if (i < 0 || i == arrLen) return 0
            if (left == 0) {
                if (i == 0) return 1
                else return 0
            }
            if (dp[i][left] != -1) return dp[i][left]

            var res = 0
            res = (res + dfs(i - 1, left - 1)) % mod
            res = (res + dfs(i + 1, left - 1)) % mod
            res = (res + dfs(i, left - 1)) % mod

            dp[i][left] = res
            return res
        }

        return dfs(0, steps)
    }
}

