                this[manager[i]] = getOrDefault(manager[i], ArrayList<Int>()).apply { add(i) }
        }

        var res = 0
        with (LinkedList<Pair<Int, Int>>()){
            addLast(headID to 0)
            while(isNotEmpty()) {
                val (id, time) = removeFirst()
                res = maxOf(res, time)
                adj[id]?.forEach {
                    addLast(it to (time + informTime[id]))
                }
            }
        }

        return res
    }
}

class Solution {
    fun maxPerformance(n: Int, speed: IntArray, efficiency: IntArray, k: Int): Int {
        val mod = 1_000_000_000 + 7
        val eng = efficiency.zip(speed)
            .sortedWith(compareBy({ -it.first }))

        var res = 0L
        var speed = 0L
        val minHeap = PriorityQueue<Int>()
        for ((eff, spd) in eng) {
            if (minHeap.size == k)
                speed -= minHeap.poll()
            speed += spd
            minHeap.add(spd)
            res = maxOf(res, speed * eff)
        }

        return (res % mod).toInt()
    }
}

class UndergroundSystem() {

    val checkIn = HashMap<Int, Pair<String, Int>>() // id -> (startStation to time)
    val averageTime = HashMap<String, Pair<Double, Int>>() // startion -> (TotalTime to countOfTrips)

    fun checkIn(id: Int, start: String, startTime: Int) {
        checkIn[id] = start to startTime
    }

    fun checkOut(id: Int, end: String, endTime: Int) {
        val (start, startTime) = checkIn[id]!!
        val fromTo = "$start:$end"
        val (total, count) = averageTime.getOrDefault(fromTo, 0.0 to 0)
        averageTime[fromTo] = (total + endTime - startTime) to (count + 1)
    }

