        val (total, count) = averageTime.getOrDefault("$start:$end", 0.0 to 0)
        return total / count
    }

}

class Solution {
    fun longestDiverseString(a: Int, b: Int, c: Int): String {
        val maxHeap = PriorityQueue<Pair<Char, Int>> { a, b ->
            b.second - a.second
         }.apply {
            if (a > 0) add('a' to a)
            if (b > 0) add('b' to b)
            if (c > 0) add('c' to c)
        }

        val res = StringBuilder()
        while (maxHeap.isNotEmpty()) {
            var (c, v) = maxHeap.poll()
            var n = res.length

            if (n > 1 && res.get(n - 1) == c && res.get(n - 2) == c) {
                if (maxHeap.isEmpty()) break
                var (c2, v2) = maxHeap.poll()
                res.append(c2)
                v2--
                if (v2 > 0) maxHeap.add(c2 to v2)
            } else {
                res.append(c)
                v--
            }

            if (v > 0) maxHeap.add(c to v)
        }

        return res.toString()
    }
}

class Solution {
    fun stoneGameIII(s: IntArray): String {
        val dp = IntArray(s.size) { Integer.MIN_VALUE }

        fun dfs(i: Int): Int {
            if (i == s.size)
                return 0
            if (dp[i] != Integer.MIN_VALUE)
                return dp[i]

            var total = 0
            for (j in i until minOf(i + 3, s.size)) {
                total += s[j]
                dp[i] = maxOf(dp[i], total - dfs(j + 1))
            }

            return dp[i]
        }

        val sum = dfs(0)
        return if (sum > 0) "Alice" else if (sum < 0) "Bob" else "Tie"
    }
}

