/**
 * Example:
 * var ti = TreeNode(5)
 * var v = ti.`val`
 * Definition for a binary tree node.
 * class TreeNode(var `val`: Int) {
 *     var left: TreeNode? = null
 *     var right: TreeNode? = null
 * }
 */
class Solution {
    fun goodNodes(root: TreeNode?): Int {
        return goodNodes(root, root!!.`val`)
    }

    fun goodNodes(node: TreeNode?, parent: Int): Int {
        if (node == null)
            return 0;

        val res = if (parent > node.`val`) 0 else 1;

        val max = Math.max(parent, node.`val`);

        val left = goodNodes(node.left, max);
        val right = goodNodes(node.right, max);

        return res + left + right;
    }
}

class Solution {
    fun maxVowels(s: String, k: Int): Int {
        val vowels = hashSetOf('a', 'e', 'i', 'o', 'u')

        var count = 0
        var max = 0
        var i = 0

        while (i < k) {
            if (s[i] in vowels) count++
            max = maxOf(max, count)
            i++
        }

        while (i < s.length) {
            count += if (s[i] in vowels) 1 else 0
            count -= if (s[i - k] in vowels) 1 else 0
            max = maxOf(max, count)
            i++
        }

        return max
    }
}

class Solution {
    fun pseudoPalindromicPaths (root: TreeNode?): Int {
        val count = IntArray (10)
        var odd = 0

        fun dfs(node: TreeNode?): Int {
            node ?: return 0

            count[node.`val`]++
            val oddChange = if (count[node.`val`] % 2 == 1) 1 else -1
            odd += oddChange

            var res = 0
            if (node.left == null && node.right == null)
                res = if (odd <= 1) 1 else 0
            else
                res = dfs(node.left) + dfs(node.right)

            odd -= oddChange
            count[node.`val`]--

            return res
        }

        return dfs(root)
    }
}

