class Solution {
    fun checkIfPrerequisite(
        numCourses: Int,
        prerequisites: Array<IntArray>,
        queries: Array<IntArray>
    ): List<Boolean> {
        // { course -> [ immediate pre-requisites ] }
        val adjacencyList = mutableMapOf<Int, MutableList<Int>>()
        prerequisites.forEach { (immediatePrerequisite, course) ->
            adjacencyList.getOrPut(course) { mutableListOf() }.add(immediatePrerequisite)
        }
        // { course -> [ complete set of prerequisites including transitive pre-requisites ] }
        val prerequisitesMap = mutableMapOf<Int, HashSet<Int>>()
        fun dfs(startCourse: Int, currentCourse: Int = startCourse) {
            if (currentCourse in (prerequisitesMap[startCourse] ?: hashSetOf())) return
            if (currentCourse != startCourse) {
                prerequisitesMap.getOrPut(startCourse) { hashSetOf() }.add(currentCourse)
            }
            for (immediatePrerequisite in adjacencyList[currentCourse] ?: mutableListOf()) {
                dfs(startCourse, immediatePrerequisite)
            }
        }

        for (course in 0 until numCourses) {
            dfs(startCourse = course)
        }

        val resultantList = mutableListOf<Boolean>()
        queries.forEach { (prerequisite, course) ->
            resultantList.add(prerequisitesMap[course]?.let { prerequisite in it } ?: false)
        }
        return resultantList
    }
}

// DP top-dowm approach
class Solution {
    fun cherryPickup(grid: Array<IntArray>): Int {
        val rows = grid.size
        val cols = grid[0].size
        var dp = Array (cols) { IntArray (cols) }

        for (r in (rows - 1) downTo 0) {
            val curDP = Array (cols) { IntArray (cols) }
            for (c1 in 0 until cols) {
                for (c2 in c1 + 1 until cols) {
                    var max = 0
                    val curPick = grid[r][c1] + grid[r][c2]
                    for (c12 in arrayOf(-1, 0, 1)) {
                        for (c22 in arrayOf(-1, 0, 1)) {
                            val nC1 = c1 + c12
                            val nC2 = c2 + c22
                            if (nC1 < 0 || nC2 == cols) continue
                            max = maxOf(
                                max,
                                curPick + dp[nC1][nC2]
                            )
                        }
                    }
                    curDP[c1][c2] = max
                }
            }
            dp = curDP
        }

        return dp[0][cols - 1]
    }
}

// Recursion + Memoization
class Solution {
    fun cherryPickup(grid: Array<IntArray>): Int {
        val rows = grid.size
        val cols = grid[0].size
        val dp = HashMap<String, Int>()

        fun dfs(r: Int, c1: Int, c2: Int): Int {
            if (c1 == c2 || minOf(c1, c2) < 0 || maxOf(c1, c2) == cols) return 0
            dp["$r:$c1:$c2"]?.let { return it }
            if (r == rows - 1) return grid[r][c1] + grid[r][c2]

            var res = 0
            for (c12 in arrayOf(-1, 0, 1)) {
                for (c22 in arrayOf(-1, 0, 1)) {
                    res = maxOf(
                        res,
                        dfs(r + 1, c1 + c12, c2 + c22)
                    )
                }
            }

            res += grid[r][c1] + grid[r][c2]
            dp["$r:$c1:$c2"] = res
            return res
        }

        return dfs(0, 0, cols - 1)
    }
}

/*
* DFS Solution
*/
class Solution {
    fun minReorder(n: Int, connections: Array<IntArray>): Int {

        val neighbors = ArrayList<ArrayList<Int>>().apply {
            for (i in 0 until n)
                this.add(ArrayList<Int>())
            for ((u,v) in connections) {
                this.get(u).apply { this.add(v) }
                this.get(v).apply { this.add(u) }
            }
        }

        val edges = HashSet<String>().apply {
            for ((u,v) in connections)
                this.add("$u:$v")
        }

        var changes = 0
        val visited = BooleanArray(n)

        fun dfs(n: Int) {
            for (nei in neighbors[n]) {
                if (visited[nei] == true)
                    continue
                if ("$nei:$n" !in edges)
                    changes++
                visited[nei] = true
                dfs(nei)
            }
        }

        visited[0] = true
        dfs(0)

        return changes
    }
}

/*
* BFS Solution
*/
class Solution {
    fun minReorder(n: Int, connections: Array<IntArray>): Int {
        // node -> (adjacentNode,isArtificialEdge)
        val adjacencyList = mutableMapOf<Int, MutableList<Pair<Int, Boolean>>>()
        connections.forEach { (u, v) -> // O(E)
            adjacencyList.getOrPut(u) { mutableListOf() }.add(Pair(v, false))
            adjacencyList.getOrPut(v) { mutableListOf() }.add(Pair(u, true))
        }
        val queue = LinkedList<Int>().apply { add(0) }
        val visitedNodes = hashSetOf<Int>().apply { add(0) }
        var minNumberOfEdgesToReOrient = 0
        while (queue.isNotEmpty()) {
            val removedNode = queue.remove()
            for ((adjacentNode, isConnectedArtificially) in adjacencyList[removedNode] ?: mutableListOf()) {
                if (adjacentNode in visitedNodes) continue
                if (!isConnectedArtificially) minNumberOfEdgesToReOrient++
                visitedNodes.add(adjacentNode)
                queue.add(adjacentNode)
            }
        }
        return minNumberOfEdgesToReOrient
    }
}

class Solution {
    fun shuffle(nums: IntArray, n: Int): IntArray {

        val res = IntArray(2 * n)
        var firstHalf = 0
        var secondHalf = n

        for (i in 0 until 2*n) {
            if (i % 2 == 0) {
                res[i] = nums[firstHalf++]
            } else {
                res[i] = nums[secondHalf++]
            }
        }

        return res
    }
}

