        size = 1
    }

    fun visit(url: String) {
        if(history.size < index + 2)
            history.add(url)
        else
            history[index + 1] = url
        index++
        size = index + 1
    }

    fun back(steps: Int): String {
        index = maxOf(index - steps, 0)
        return history[index]
    }

    fun forward(steps: Int): String {
        index = minOf(index + steps, size - 1)
        return history[index]
    }
}

