// Use of buckets
class Solution {
    fun findLeastNumOfUniqueInts(arr: IntArray, k: Int): Int {
        val n = arr.size
        val counts = HashMap<Int, Int> ()
        val buckets = HashMap<Int, Int> ()

        arr.forEach { n ->
            counts[n] = (counts[n] ?: 0) + 1
        }

        counts.values.forEach { count ->
            buckets[count] = (buckets[count] ?: 0) + 1
        }

        var k = k
        var res = counts.size
        for (n in 1 until buckets.size) {
            var remove = buckets[n] ?: 0
            val total = n * remove
            if (k >= total) {
                k -= total
                res -= remove
            } else {
                remove = k / n
                res -= remove
                break
            }
        }

        return res
    }
}

// Use a heap
 class Solution {
    fun findLeastNumOfUniqueInts(arr: IntArray, k: Int): Int {
        val freq = HashMap<Int, Int> ()
        arr.forEach { n ->
            freq[n] = (freq[n] ?: 0) + 1
        }

        val heap = PriorityQueue<Int> { a, b -> a - b }
        heap.addAll(freq.values)

        var k = k
        var res = heap.size
        while (k > 0 && heap.isNotEmpty()) {
            val f = heap.poll()
            if (k >= f) {
                k -= f
                res -= 1
            }
        }

        return res
    }
}

class Solution {

    class UnionFind(val n: Int) {
        val par = IntArray (n) { it }
        val rank = IntArray (n) { 1 }

        fun find(x: Int): Int {
            if (par[x] != x)
                par[x] = find(par[x])
            return par[x]
        }

        fun union(x: Int, y: Int): Boolean {
            val px = find(x)
            val py = find(y)
            if (px == py) return false
            if (rank[px] > rank[py]) {
                par[py] = px
                rank[px] += rank[py]
            } else {
                par[px] = py
                rank[py] += rank[px]
            }
            return true
        }
    }

    fun findCriticalAndPseudoCriticalEdges(n: Int, _edges: Array<IntArray>): List<List<Int>> {
        val edges = _edges.mapIndexed { i, v ->
            intArrayOf(v[0], v[1], v[2], i)
        }.sortedWith(
            Comparator { a, b ->
                a[2] - b[2]
            }
        )

        var mstWeight = 0
        val uf = UnionFind (n)
        for ((u, v, w, i) in edges) {
            if (uf.union(u, v)) mstWeight += w
        }

        val crit = mutableListOf<Int>()
        val pseudo = mutableListOf<Int>()
        for ((u, v, w, i) in edges) {
            val uf2 = UnionFind (n)
            var mstWeightWithout = 0
            for ((u2, v2, w2, i2) in edges) {
                if (i != i2 && uf2.union(u2, v2))  mstWeightWithout += w2
            }
            if (uf2.rank.max()!! != n || mstWeightWithout > mstWeight) {
                crit.add(i)
                continue
            }

            val uf3 = UnionFind (n)
            uf3.union(u, v)
            var mstWeightWith = w
            for ((u3, v3, w3, i3) in edges) {
                if (uf3.union(u3, v3))  mstWeightWith += w3
            }
            if (mstWeightWith == mstWeight) pseudo.add(i)
        }

        return listOf(crit, pseudo)
    }
}

class Solution {
    fun isPathCrossing(path: String): Boolean {
        var dirs = mapOf(
            'N' to intArrayOf(0, 1),
            'S' to intArrayOf(0, -1),
            'E' to intArrayOf(1, 0),
            'W' to intArrayOf(-1, 0),
        )
        val visit = HashSet<Pair<Int, Int>>()
        var x = 0
        var y = 0

        for (c in path) {
            visit.add(x to y)
            val (dx, dy) = dirs[c]!!
            x += dx
            y += dy
            if ((x to y) in visit)
                return true
        }

        return false
    }
}

class Solution {
    fun numSubseq(nums: IntArray, target: Int): Int {
        nums.sort()
        val mod = 1000000000 + 7

        val pow = IntArray(nums.size)
        pow[0] = 1
        for (i in 0 until nums.size - 1)
            pow[i + 1] = pow[i] * 2 % mod

        var left = 0
        var right = nums.lastIndex
        var res = 0
        while (left <= right) {
            if (nums[left] + nums[right] > target) {
                right--
            } else {
                res = (res + pow[right - left]) % mod
                left++
            }
        }

        return res
    }
}

