class Solution {
    fun minDays(n: Int): Int {
        val dp = HashMap<Int, Int>().apply {
            this[0] = 0
            this[1] = 1
        }

        fun dfs(n: Int): Int {
            if (n in dp) return dp[n]!!

            val divByTwo = 1 + (n % 2) + dfs(n / 2)
            val divByThree = 1 + (n % 3) + dfs(n / 3)

            dp[n] = minOf(
                divByTwo,
                divByThree
            )

            return dp[n]!!
        }

        return dfs(n)
    }
}

