class Solution {
    fun minDays(n: Int): Int {
        val q = LinkedList<Int>().apply { add(n) }
        val visited = HashSet<Int>()
        var days = 1

        while (q.isNotEmpty()) {
            repeat (q.size) {
                val n = q.removeFirst()
                if (n == 1 || n == 0) return days
                if (n !in visited) {
                    visited.add(n)
                    q.addLast(n - 1)
                    if (n % 2 == 0) q.addLast(n / 2)
                    if (n % 3 == 0) q.addLast(n / 3)
                }
            }
            days++
        }

        return days
    }
}

