    fun isEvenOddTree(root: TreeNode?): Boolean {
        val q = LinkedList<TreeNode?> ().apply { addLast(root) }
        var even = true

        while (q.isNotEmpty()) {
            var prev = if (isEven) Integer.MIN_VALUE else Integer.MAX_VALUE

            repeat (q.size) {
                val node = q.removeFirst()!!

                if (even && (node.`val` % 2 == 0 || node.`val` <= prev))
                    return false
                else if (!even && (node.`val` % 2 == 1 || node.`val` >= prev))
                    return false

                prev = node.`val`

                node.left?.let { q.addLast(it) }
                node.right?.let { q.addLast(it) }
            }

            even = !even
        }

        return true
    }
}

class Solution {
    fun minimumOneBitOperations(n: Int): Int {
        if (n == 0) return 0

        var k = 0
        while (2 p k <= n)
            k++
        k -= 1

        return (2 p (k + 1)) - 1 - minimumOneBitOperations((2 p k) xor n)
    }

    infix fun Int.p(k: Int) = Math.pow(this.toDouble(), k.toDouble()).toInt()
}

