class Solution {
    fun minInterval(intervals: Array<IntArray>, _queries: IntArray): IntArray {
        intervals.sortWith(compareBy( {it[0]}, { it[1]}))
        val queries = _queries.withIndex().sortedBy { it.value }
        val minHeap = PriorityQueue<IntArray> (compareBy( { it[0] }, { it[1] }))
        val res = IntArray (queries.size)

        var i = 0
        queries.forEach { (idx, q) ->
            while (i < intervals.size && intervals[i][0] <= q) {
                val (l, r) = intervals[i]
                minHeap.add(intArrayOf(r - l + 1, r))
                i++
            }

            while (minHeap.isNotEmpty() && minHeap.peek()[1] < q)
                minHeap.poll()

            res[idx] = if (minHeap.isEmpty()) -1 else minHeap.peek()[0]
        }

        return res
    }
}

class Solution {
    fun maxSumMinProduct(nums: IntArray): Int {
        val prefix = LongArray(nums.size + 1)
        val stack = ArrayDeque<Pair<Int, Long>>()
        val mod = 1000000007L

        for (i in nums.indices) {
            prefix[i + 1] = prefix[i] + nums[i]
        }

        var res = 0L
        for ((i, n) in nums.withIndex()) {
            var start = i

            while (stack.isNotEmpty() && stack.peekLast().second > n) {
                val (lastStart, value) = stack.removeLast()
                val total = prefix[i] - prefix[lastStart]
                res = maxOf(res, total * value)
                start = lastStart
            }

            stack.addLast(start to n.toLong())
        }

        for ((start, value) in stack) {
            val total = prefix[nums.size] - prefix[start]
            res = maxOf(res, total * value)
        }


        return (res % mod).toInt()
    }
}

class Solution {
    fun largestPathValue(colors: String, edges: Array<IntArray>): Int {
        val adj = HashMap<Int, ArrayList<Int>>()
        for ((from, to) in edges)
            adj[from] = adj.getOrDefault(from, ArrayList<Int>()).apply{this.add(to)}

        val visited = HashSet<Int>()
        val path = HashSet<Int>()
        val count = Array(colors.length){IntArray(26)}

        fun dfs(node: Int): Int {
            if (node in path)
                return Integer.MAX_VALUE
            if (node in visited)
                return 0

            visited.add(node)
            path.add(node)

            val colorIndex = colors[node] - 'a'
            count[node][colorIndex] = 1

            adj[node]?.forEach{ nei ->
                if (dfs(nei) == Integer.MAX_VALUE)
                    return Integer.MAX_VALUE
                (0 until 26).forEach{ c ->
                    count[node][c] = maxOf(
                        count[node][c],
                        count[nei][c] + if(c == colorIndex) 1 else 0
                    )
                }
            }

            path.remove(node)
            return count[node].max()!!
        }

        var res = 0
        for (i in 0 until colors.length) {
            res = maxOf(res, dfs(i))
        }

        return if(res == Integer.MAX_VALUE) -1 else res
    }
}

// Dp bottom up
class Solution {
    fun rearrangeSticks(n: Int, k: Int): Int {
        val mod = 1_000_000_000 + 7
        val dp = Array (n + 1) { LongArray (k + 1) }

        dp[1][1] = 1
        for (i in 2..n) {
            for (j in 1..k) {
                dp[i][j] = (dp[i - 1][j - 1] + ((i - 1) * dp[i - 1][j])) % mod
            }
        }

        return dp[n][k].toInt()
    }
}

// Recursion + memoization
class Solution {
    fun rearrangeSticks(n: Int, k: Int): Int {
        val mod = 1_000_000_000 + 7
        val dp = Array (n + 1) { LongArray (k + 1) { -1L } }

        fun dfs(n: Int, k: Int): Long {
            if (n == k) return 1
            if (n == 0 || k == 0) return 0
            if (dp[n][k] != -1L) return dp[n][k]

            dp[n][k] = dfs(n - 1, k - 1) + ((n - 1) * dfs(n - 1, k))

            return dp[n][k] % mod
        }

        return dfs(n, k).toInt()
    }
}

/*
* O(n) BFS
*/
class Solution {
    fun canReach(s: String, minJump: Int, maxJump: Int): Boolean {
        val q = LinkedList<Int>().apply { add(0) }
        var farthest = 0

        with (q) {
            while (isNotEmpty()) {
                val i = removeFirst()
                val start = maxOf(i + minJump, farthest + 1)

                for (j in start until minOf(i + maxJump + 1, s.length)) {
                    if (s[j] == '0') {
                        if (j == s.lastIndex)
                            return true
                        addLast(j)
                    }
                }

                farthest = i + maxJump
            }
        }

        return false
    }
}

/*
* O(n) DP
*/
class Solution {
    fun canReach(s: String, minJump: Int, maxJump: Int): Boolean {
        val dp = BooleanArray(s.length).apply { this[0] = true }

        var cntOfPos = 0
        for (i in 1 until s.length) {
            if (i - minJump >= 0 && dp[i - minJump])
                cntOfPos++
            if (i - maxJump > 0 && dp[i - maxJump - 1])
                cntOfPos--
            dp[i] = cntOfPos > 0 && s[i] == '0'
        }

        return dp[s.lastIndex]
    }
}

class Solution {
    fun assignTasks(servers: IntArray, tasks: IntArray): IntArray {
