class Solution {
    fun countSubIslands(grid1: Array<IntArray>, grid2: Array<IntArray>): Int {

        fun isValid(i: Int, j: Int) = i in (0 until grid2.size) && j in (0 until grid2[0].size) && grid2[i][j] == 1

        val dir = arrayOf(
            intArrayOf(1,0),
            intArrayOf(-1,0),
            intArrayOf(0,1),
            intArrayOf(0,-1)
        )

        fun dfs(i: Int, j: Int): Boolean {
            if(grid1[i][j] != 1)
                return false
            grid2[i][j] = 0
            var found = true
            for((iD,jD) in dir){
                val iN = i + iD
                val jN = j + jD
                if(isValid(iN, jN))
                  found = found and dfs(iN, jN)
            }
            return found
        }

        var count = 0
        for(i in 0 until grid1.size){
            for(j in 0 until grid1[0].size){
                if(grid1[i][j] == 1 && grid2[i][j] == 1)
                    if(dfs(i, j) == true)
                        count++
            }
        }
        return count
    }
}

class Solution {
    fun maxAlternatingSum(nums: IntArray): Long {
        val dp = Array (2) { LongArray (nums.size) { -1L } }

        fun dfs(i: Int, even: Int): Long {
            if (i == nums.size)
                return 0
            if (dp[even][i] != -1L)
                return dp[even][i]

            var sum = if (even == 1) nums[i] else -1 * nums[i]
            dp[even][i] = maxOf(
                sum + dfs(i + 1, if (even == 1) 0 else 1),
                dfs(i + 1, even)
            )

            return dp[even][i]
        }

        return dfs(0, 1)
    }
}

class Solution {
    fun maxProductDifference(nums: IntArray): Int {
        var max1 = Integer.MIN_VALUE
        var max2 = Integer.MIN_VALUE
        var min1 = Integer.MAX_VALUE
        var min2 = Integer.MAX_VALUE
        for (n in nums) {
            if (n > max1) {
                max2 = max1
                max1 = n
            } else {
                max2 = maxOf(max2, n)
            }

            if (n < min1) {
                min2 = min1
                min1 = n
            } else {
                min2 = minOf(min2, n)
            }
        }

        return max1 * max2 - min1 * min2
    }
}

