        for (i in 1 until nums.lastIndex) {
            if (nums[i - 1] < nums[i] && nums[i] < nums[i + 1] ||
                nums[i - 1] > nums[i] && nums[i] > nums[i + 1])
                nums[i] = nums[i + 1].also { nums[i + 1] = nums[i] }
