class DetectSquares() {

    val hm = HashMap<Pair<Int, Int>, Int>() // [[x, y], count]

    fun add(point: IntArray) {
        hm[point[0] to point[1]] = hm.getOrDefault(point[0] to point[1], 0) + 1
    }

    fun count(point: IntArray): Int {
        var count = 0
        val (x,y) = point
        for((k, v) in hm){
            repeat(v){ //incase of >1 occurences, we do calculations for each occurence
                val (mX, mY) = k
                if(Math.abs(mX - x) == Math.abs(mY - y) && x != mX && y != mY){
                    count += hm.getOrDefault(x to mY, 0) * hm.getOrDefault(mX to y, 0) //0 if the possible point doesnt exist
                }
            }
        }
        return count
    }

}

class Solution {
    fun gridGame(grid: Array<IntArray>): Long {
        val n = grid[0].size
        val topPrefix = LongArray(n)
        val botPrefix = LongArray(n)

        for (i in 0 until n) {
            topPrefix[i] = grid[0][i].toLong()
            botPrefix[i] = grid[1][i].toLong()
            if (i > 0 ) {
                topPrefix[i] += topPrefix[i - 1]
                botPrefix[i] += botPrefix[i - 1]
            }
        }

        var res = Long.MAX_VALUE
        for (i in 0 until n) {
            val rob2top = topPrefix[n - 1] - topPrefix[i]
            val rob2bot = if (i > 0) botPrefix[i - 1] else 0L

            val rob2take = maxOf(
                rob2top,
                rob2bot
            )

            res = minOf(
                res,
                rob2take
            )
        }

        return res
    }
}

class Solution {
    fun missingRolls(rolls: IntArray, mean: Int, _n: Int): IntArray {
        val m = rolls.size
        var n = _n
        var nTotal = (mean * (n + m)) - (rolls.sum() ?: 0)

        if (nTotal < n || nTotal > n * 6)
            return IntArray (0)

        var res = LinkedList<Int>()
        while (nTotal > 0) {
            val dice = minOf(nTotal - n + 1, 6)
            res.add(dice)
            nTotal -= dice
            n--
        }

        return res.toIntArray()
    }
}

