class Solution {
    fun minimumTime(n: Int, relations: Array<IntArray>, time: IntArray): Int {
        val adj = HashMap<Int, MutableList<Int>>().apply {
            for ((src, dst) in relations) {
                this[src] = getOrDefault(src, mutableListOf<Int>()).apply {
                    add(dst)
                }
            }
        }


        val maxTime = IntArray (n + 1) { -1 }
        fun dfs(src: Int): Int {
            if (maxTime[src] != -1) return maxTime[src]

            var res = time[src - 1]
            adj[src]?.forEach { nei ->
                res = maxOf(res, time[src - 1] + dfs(nei))
            }

            maxTime[src] = res
            return res
        }

        for (i in 1..n)
            dfs(i)

        return maxTime.max()!!
    }
}

class Solution {
    fun findAllPeople(n: Int, meetings: Array<IntArray>, firstPerson: Int): List<Int> {
        val secrets = mutableSetOf(0, firstPerson)
        val timeMap = mutableMapOf<Int, MutableMap<Int, MutableList<Int>>>()

        for ((src, dst, t) in meetings) {
            if (t !in timeMap)
                timeMap[t] = mutableMapOf()
            timeMap[t]!!.getOrPut(src) { mutableListOf() }.apply { add(dst) }
            timeMap[t]!!.getOrPut(dst) { mutableListOf() }.apply { add(src) }
        }

        fun dfs(
            src: Int,
            adj: MutableMap<Int, MutableList<Int>>,
            visit: MutableSet<Int>
        ) {
            if (src in visit) return
            visit.add(src)
            secrets.add(src)
            adj[src]?.forEach { nei ->
                dfs(nei, adj, visit)
            }
        }

        timeMap.keys.sorted().forEach { t ->
            val visit = mutableSetOf<Int> ()
            timeMap[t]?.keys?.forEach { src ->
                if (src in secrets) {
                    dfs(src, timeMap[t]!!, visit)
                }
            }
        }

        return secrets.toList()
    }
}

class Solution {
    fun maximumDetonation(b: Array<IntArray>): Int {
        val adj = HashMap<Int, ArrayList<Int>>().apply {
            for (i in b.indices) {
                for (j in b.indices) {
                    if (i != j) {
                        val dX = b[i][0].toDouble() - b[j][0].toDouble()
                        val dY = b[i][1].toDouble() - b[j][1].toDouble()
                        if ((b[i][2].toDouble() * b[i][2].toDouble()) >= (dX * dX + dY * dY))
                            this[i] = getOrDefault(i, ArrayList<Int>()).apply { add(j) }
                    }
                }
            }
        }

        fun dfs(i: Int, visit: HashSet<Int>) {
            if (i in visit)
                return
            visit.add(i)
            adj[i]?.forEach {
                dfs(it, visit)
            }
        }

        var res = 0
        for (i in b.indices) {
            val visit = HashSet<Int>()
            dfs(i, visit)
            res = maxOf(
                res,
                visit.size
            )
        }

        return res
    }
}

