/**
 * Example:
 * var li = ListNode(5)
 * var v = li.`val`
 * Definition for singly-linked list.
 * class ListNode(var `val`: Int) {
 *     var next: ListNode? = null
 * }
 */
class Solution {
    fun pairSum(head: ListNode?): Int {
        var slow = head
        var fast = head
        var prev: ListNode? = null

        while(fast != null && fast.next != null) {
            fast = fast.next.next
            val temp = slow?.next
            slow?.next = prev
            prev = slow
            slow = temp
        }

        var res = 0
        while(slow != null && prev != null) { // only need to check if either one of these != null, I check both for null safety warnings
            res = maxOf(res, slow.value!! + prev.value!!)
            prev = prev.next
            slow = slow.next
        }

        return res
    }

    val ListNode.value get()= this.`val`
}

/*
* DFS/Recursion + Memoization
*/
class Solution {
    fun mostPoints(questions: Array<IntArray>): Long {
        val memo = LongArray(questions.size) { -1L }

        fun dfs(i: Int): Long {
            if (i >= questions.size)
                return 0
            if (memo[i] != -1L)
                return memo[i]

            memo[i] = maxOf(
                questions[i][0] + dfs(i + 1 + questions[i][1]),
                dfs(i + 1)
            )

            return memo[i]
        }

        return dfs(0)
    }
}

/*
* DP
*/
class Solution {
    fun mostPoints(q: Array<IntArray>): Long {
        val n = q.lastIndex
        val dp = LongArray(q.size)

        for (i in n downTo 0) {
            dp[i] = maxOf(
                if (i < n) dp[i + 1] else 0,
                q[i][0] + if (i + 1 + q[i][1] <= n) dp[i + 1 + q[i][1]] else 0
            )
        }

        return dp[0]
    }
}

