class Solution {
    fun maxValueOfCoins(piles: List<List<Int>>, k: Int): Int {
        val n = piles.size
        val dp = Array(n){ IntArray(k+1){-1} }

        fun dfs(i: Int, coins: Int): Int {
            if (i == n)
                return 0
            if (dp[i][coins] != -1)
                return dp[i][coins]

            dp[i][coins] = dfs(i + 1, coins)

            var curPile = 0
            for (j in 0 until minOf(piles[i].size, coins)) {
                curPile += piles[i][j]
                dp[i][coins] = maxOf(
                    dp[i][coins],
                    curPile + dfs(i + 1, coins - j - 1)
                )
            }

            return dp[i][coins]
        }

        return dfs(0, k)
    }
}

// two heaps
class Solution {
    fun fullBloomFlowers(flowers: Array<IntArray>, _people: IntArray): IntArray {
        val people = _people.mapIndexed { i, p -> p to i }.sortedBy { it.first }
        val res = IntArray (_people.size)
        var count = 0
        val start = PriorityQueue<Int>()
        val end = PriorityQueue<Int>()

        for ((s, e) in flowers) {
            start.add(s)
            end.add(e)
        }

        for ((p, i) in people) {
            while (start.isNotEmpty() && start.peek() <= p) {
                start.poll()
                count++
            }

            while (end.isNotEmpty() && end.peek() < p) {
                end.poll()
                count--
            }

            res[i] = count
        }

        return res
    }
}

// one heap
class Solution {
    fun fullBloomFlowers(flowers: Array<IntArray>, _people: IntArray): IntArray {
        val people = _people.mapIndexed { i, p -> p to i }.sortedBy { it.first }
        val res = IntArray (_people.size)
        flowers.sortBy { it[0] }
        val end = PriorityQueue<Int>()

        var j = 0
        for ((p, i) in people) {
            while (j < flowers.size && flowers[j][0] <= p) {
                end.add(flowers[j][1])
                j++
            }

            while (end.isNotEmpty() && end.peek() < p)
                end.poll()

            res[i] = end.size
        }

        return res
    }
}

