/*
* Recursion/DFS + memoization
*/
class Solution {
    fun countGoodStrings(low: Int, high: Int, zero: Int, one: Int): Int {
        val dp = IntArray(high + 1) { -1 }
        val mod = 1000000007

        fun dfs(i: Int): Int {
            if (i > high)
                return 0
            if (dp[i] != -1)
                return dp[i]

            dp[i] = if (i >= low) 1 else 0
            dp[i] += dfs(i + zero) + dfs(i + one)
            dp[i] = dp[i] % mod

            return dp[i]
        }

        return dfs(0)
    }
}

/*
* Bottom up DP
*/
class Solution {
    fun countGoodStrings(low: Int, high: Int, zero: Int, one: Int): Int {
        val dp = IntArray(high + 1)
        val mod = 1000000007

        dp[0] = 1
        for (i in 1..high) {
            dp[i] += if (i - one >= 0) dp[i - one] else 0
            dp[i] += if (i - zero >= 0) dp[i - zero] else 0
            dp[i] = dp[i] % mod
        }

        var sum = 0
        for (i in low..high) sum = (sum + dp[i]) % mod
        return sum
    }
}

class Solution {
    fun minimumFuelCost(roads: Array<IntArray>, seats: Int): Long {

        var result = 0.0
        if (roads.size == 0) return result.toLong()

        val adj = HashMap<Int, ArrayList<Int>>()
        for (road in roads){
            adj[road[0]] = adj.getOrDefault(road[0], ArrayList<Int>()).apply { this.add(road[1]) }
            adj[road[1]] = adj.getOrDefault(road[1], ArrayList<Int>()).apply { this.add(road[0]) }
        }

        fun dfs(node: Int, parent: Int): Double {

            var passengers = 0.0
            var res = 0.0
            for (child in adj[node]!!) {
                if (child != parent) {
                    val childPassengers = dfs(child, node)
                    passengers += childPassengers
                    result += Math.ceil(childPassengers / seats)
                }
            }

            return passengers + 1.0
        }

        dfs(0, -1)
        return result.toLong()
    }
}

// Time O(n) and space O(n) with prefix/suffix sums
class Solution {
    fun bestClosingTime(c: String): Int {
        val n = c.length
        val prefix = IntArray (n + 1)
        val postfix = IntArray (n + 1)

        for (i in 1..n) {
            prefix[i] = prefix[i - 1] + if (c[i - 1] == 'N') 1 else 0
        }

        for (i in n - 1 downTo 0) {
            postfix[i] = postfix[i + 1] + if (c[i] == 'Y') 1 else 0
        }

        var res = Integer.MAX_VALUE
        var min = Integer.MAX_VALUE
        for (i in 0..n) {
            val pen = prefix[i] + postfix[i]
            if (pen < min) {
                min = pen
                res = i
            }
        }

        return res
    }
}

