class Solution {
    fun minScore(n: Int, roads: Array<IntArray>): Int {
        var res = Integer.MAX_VALUE
        val adj = HashMap<Int, ArrayList<Pair<Int, Int>>>()

        for((a,b,d) in roads) {
            adj[a] = adj.getOrDefault(a, ArrayList()).apply{
                this.add(b to d)
            }
            adj[b] = adj.getOrDefault(b, ArrayList()).apply{
                this.add(a to d)
            }
        }

        val visited = HashSet<Int>()

        fun dfs(curr: Int) {
            if(curr in visited)
                return
            visited.add(curr)
            for((neigh, dist) in adj[curr]!!) {
                res = minOf(res, dist)
                dfs(neigh)
            }
        }

        dfs(1)
        return res
    }
}

class Solution {
    fun maxScore(nums1: IntArray, nums2: IntArray, k: Int): Long {
        val nums = nums1.zip(nums2).sortedWith(compareBy({ -it.second }))
        val minHeap = PriorityQueue<Int>()

        var sum = 0L
        var res = 0L
        for ((n1, n2) in nums) {
            sum += n1
            minHeap.add(n1)

            if (minHeap.size > k)
                sum -= minHeap.poll()
            if (minHeap.size == k)
                res = maxOf(res, sum * n2)
        }

        return res
    }
}

class Solution {
    fun findMatrix(nums: IntArray): List<List<Int>> {
        val count = HashMap<Int, Int>()
        val res = mutableListOf<MutableList<Int>>()

        for (n in nums) {
            var row = count[n] ?: 0
            if (res.size == row)
                res.add(mutableListOf<Int>())
            res[row].add(n)
            count[n] = (count[n] ?: 0) + 1
        }

        return res
    }
}

class Solution {
    fun minimizeMax(nums: IntArray, p: Int): Int {
        if (p == 0) return 0

        val n = nums.size
        nums.sort()

        fun good(x: Int): Boolean {
            var i = 0
            var count = 0
            while (i < n - 1) {
                if ((nums[i + 1] - nums[i]) <= x) {
                    count++
                    i += 2
                } else {
                    i++
                }
                if (count == p) return true
            }
            return false
        }

        var l = 0
        var r = 1000000000
        while (l < r) {
            val m = l + (r - l) / 2
            if (good(m)) {
                r = m
            } else {
                l = m + 1
            }
        }

        return l
    }
}

class Solution {
    fun buyChoco(prices: IntArray, money: Int): Int {
        var min1 = Integer.MAX_VALUE
        var min2 = Integer.MAX_VALUE

        for (p in prices) {
            if (p < min1) {
                min2 = min1
                min1 = p
            } else {
                min2 = minOf(min2, p)
            }
        }

        val left = money - (min1 + min2)
        return if (left >= 0) left else money
    }
}

class UnionFind (val n: Int) {
    val parent = IntArray (n) { it }
    val size = IntArray (n) { 1 }
    var count = n

    fun find(x: Int): Int {
        if (x != parent[x])
            parent[x] = find(parent[x])
        return parent[x]
    }

    fun union(x: Int, y: Int) {
        val px = find(x)
        val py = find(y)
        if (px != py) {
            if (size[px] > size[py]) {
                parent[py] = px
                size[px] += size[py]
            } else {
                parent[px] = py
                size[py] += size[px]
            }
            count--
        }
    }
}

class Solution {
    fun canTraverseAllPairs(nums: IntArray): Boolean {
        val uf = UnionFind (nums.size)
        val factorIndex = HashMap<Int, Int>()

        for (i in nums.indices) {
            var n = nums[i]
            var f = 2

            while (f * f <= n) {
                if (n % f == 0) {
                    if (f in factorIndex)
                        uf.union(i, factorIndex[f]!!)
                    else
                        factorIndex[f] = i
                    while (n % f == 0)
                        n /= f
                }
                f++
            }

            if (n > 1) {
                if (n in factorIndex)
                    uf.union(i, factorIndex[n]!!)
                else
                    factorIndex[n] = i
            }
        }

        return uf.count == 1
    }
}

class Solution {
    fun paintWalls(cost: IntArray, time: IntArray): Int {
        val n = cost.size
        val dp = Array (n) { IntArray (n + 1) { -1 } }

        fun dfs(i: Int, rem: Int): Int {
            if (rem <= 0) return 0
            if (i == n) return INFINITY
            if (dp[i][rem] != -1) return dp[i][rem]

            dp[i][rem] = minOf(
                cost[i] + dfs(i + 1, rem - 1 - time[i]),
                dfs(i + 1, rem)
            )

            return dp[i][rem]
        }

        return dfs(0, n)
    }

    companion object {
        const val INFINITY = 500000001
    }
}

// traverse and swap indices
class Solution {
    fun maximumOddBinaryNumber(s: String): String {
        val sArr = s.toCharArray()
        var left = 0

        for (i in 0 until sArr.size) {
            if (sArr[i] == '1') {
                sArr[i] = sArr[left].also { sArr[left] = sArr[i] }
                left++
            }
        }

        sArr[left - 1] = sArr[sArr.lastIndex].also { sArr[sArr.lastIndex] = sArr[left - 1] }
        return sArr.joinToString("")
    }
}

// Count 1's and build at once
class Solution {
    fun maximumOddBinaryNumber(s: String): String {
        var count = 0
        for (c in s) {
            if (c == '1') count++
        }

        return "1".repeat(count - 1) + "0".repeat(s.length - count) + "1"
    }
}

// Rolling string builder
class Solution {
    fun maximumOddBinaryNumber(s: String) = buildString {
        var count = s.count  { it == '1' } - 1
        val n = s.length

        for (i in 0 until n - 1) {
            if (count > 0) {
                append("1")
                count--
            } else {
                append("0")
            }
        }

        append("1")
        return toString()
    }
}

class Solution {
    fun minOperations(nums: IntArray): Int {
        val count = nums.asIterable().groupingBy { it }.eachCount()

        var res = 0
        for (c in count.values) {
            if (c == 1) return -1
            res += (c / 3) + if (c % 3 > 0) 1 else 0 // "Ceil" function
        }

        return res
    }
}

class Solution {
    fun largestPerimeter(nums: IntArray): Long {
        nums.sort()
        var total = 0L
        var res = -1L

        for (n in nums) {
            if (total > n)
                res = total + n
            total += n
        }

        return res
    }
}

// Same logic but a top down approach instead of bottom up as the solution above
class Solution {
    fun largestPerimeter(nums: IntArray): Long {
        nums.sortDescending()

        var sum = 0L
        for (n in nums)
            sum += n

        for (n in nums) {
            val rest = sum - n
            if (rest > n) return sum
            sum -= n
        }

        return -1L
    }
}

/*
 * Same intuition as above but use a maxheap instead of sorting. In Kotlin and Java the time complexity is O(nlogn)
 * but using heapify in Python or priority_queue in C++ this will have a time complexity of O(logn + n) ~ O(n)
 */
class Solution {
    fun largestPerimeter(nums: IntArray): Long {
        val max = PriorityQueue<Int> { a, b -> b - a }
        var sum = 0L

        for (n in nums) {
            sum += n
            max.add(n)
        }

        while (max.isNotEmpty() && sum <= max.peek() * 2)
            sum -= max.poll()

        return if (max.size >= 2 && sum > 0L) sum else -1L
    }
}
